-- ##########################################################################################
-- RELEASE SECTION 04/7: APPLY-0263.sql
-- In plain words: Event stages: one canonical stage per quote / event worked out from existing columns, every stage change recorded by triggers (who, when, why); out-of-order moves only logged (warn mode). No existing write path changed.
-- ##########################################################################################
-- APPLY-0263.sql - paste into the Supabase SQL editor (STAGING first; production only when the owner says go).
-- Run AFTER APPLY-0254 (already applied). Order-independent of 0256-0262 (other r23 branches).
-- Event stages (r23): ONE stage for every quote / event (Lead, Draft, Sent, Viewed, Approved, Advance paid, Confirmed,
-- In progress, Event day, Completed, Closed + Cancelled, Expired, Lost) worked out from the existing columns, and
-- EVERY stage change recorded (who, when, how, why) by triggers - no existing screen, RPC or row is changed.
-- Out-of-order moves are only LOGGED (warn mode, the default). One "domain event" row per move for future automations.
-- Existing quotes get one "recorded when tracking began" row each (insert-only). Nothing deleted. Safe to run twice.
-- OWNER STEPS (staging first, then production):
--   1  Paste this whole file and Run. Every VERIFY row at the bottom must say ok = true.
--   2  Deploy the site (event.html / flow.html / control.html / stage-history.js / stage-history.css /
--      stage-machine-settings.js / store-api.js). No edge function to deploy.
--   3  Check: open an event -> "Stage history" card shows the current stage pill and its moves. Send a quote / record
--      a payment -> the new move appears ("Moved to Approved by the client - 20/10/2026, 14:05").
--      Control Center -> "Event stages": Warn (default) / Enforce, show history on / off (studio admin only).
--   Kill switch (Helm HQ operator, if ever needed): select public.hq_set_stage_machine(false, null, null);
begin;
-- 0263_quote_stage_machine.sql - CANONICAL forward-only.
-- REQUIRES 0040 + 0208 (quotes archived_* / deleted_* / link_expired_at), 0052 (lifecycle_stage, consent_stale),
--          0078 (client_link_opens), 0049 / 0198 (event_closure, event_cancellations, lifecycle_stage_overrides),
--          0045 (_hq_wgate), phase29 / phase57 / phase97 (has_area, current_org_id, user_role, app_config (org_id, key)),
--          0184 when installed (trial retention purge list gets the new studio tables).
--
-- In plain words (r23, INDUSTRY-BENCHMARK-PLAN A2 + A3 - the Salesforce / HubSpot deal-stage + Stripe event model):
--   A quote / event's state is split over three columns: status (quote / confirmed = priced and LOCKED / cancelled),
--   approval_status (none / sent / approved / paid / cancelled) and lifecycle_stage (lead .. closed, 11 stages, moved
--   by set_lifecycle_stage). Plus: archived / deleted shelves (0040 / 0141), the closure row (event_closure.closed_at)
--   and the client opening the approval link (client_link_opens kind 'quote'). This migration adds ONE canonical
--   stage on top of them WITHOUT changing a single existing write path:
--
--   1  helm_quote_stage(...) - one pure rule that folds those columns into ONE stage:
--        lead > draft > sent > viewed > approved > advance_paid > confirmed > in_progress > event_day > completed
--        > closed, plus the side stages cancelled, expired, lost. (Exact mapping in section 1 below; the app has a
--        line-for-line copy, BPStore.quoteStage, and a parity test.) View quote_stage_v = every quote + its stage.
--   2  quote_stage_transitions (append-only): from, to, actor, at, reason, source (ui / rpc / client / cron /
--        system / backfill), via (the RPC name). Written ONLY by AFTER ROW triggers on quotes (state columns only),
--        event_closure and client_link_opens - so every existing RPC, webhook, cron and trigger is covered
--        automatically. ONE MOVE PER TRANSACTION: an RPC that changes approval, lifecycle and status one after the
--        other leaves ONE row (its own provisional row is replaced, never a committed one).
--        quote_stage_current keeps the latest stage per quote (the comparison point; self-heals on read).
--   3  quote_stage_moves = the table of allowed moves (seeded once, insert-only); a move that is not in it is an
--        "illegal move". Default mode WARN: the move happens as before and is logged in quote_stage_warnings.
--        ENFORCE (HQ switch, or a studio's own Control Center switch) refuses an illegal move made by a signed-in
--        studio user (error HL423 at COMMIT, the whole change is rolled back; that deferred check is only queued
--        while some studio / HQ has ENFORCE on - in WARN nothing is queued). Client links, payment webhooks, cron jobs and
--        SQL-editor work are NEVER blocked - they are logged. HQ can also switch tracking OFF entirely (kill switch).
--   4  domain_events: every transition adds one row (type 'quote.<to_stage>', e.g. quote.approved) that
--        automations read in order with domain_events_pull(consumer, types, limit) + domain_events_ack(consumer,
--        last_id) (service role; one cursor per consumer in domain_event_cursors). Nothing is sent by this migration.
--   5  Read RPCs for the app: quote_stage_history(quote) (the event workspace / quote flow timeline: "Moved to
--        Approved by client - 20/10/2026 14:05"), quote_stage_list(ids) (stage pills on lists), stage_machine_settings
--        / set_stage_machine_settings (Control Center), hq_stage_machine / hq_set_stage_machine (HQ, counts only - no
--        studio business data).
--   6  BACKFILL (insert-only): one "recorded when tracking began" row per existing quote (source backfill, no
--        domain event - automations do not fire for history).
--   7  quote_stage_sweep(): time-based expiry (a sent link that ran out) is recorded every 30 minutes by pg_cron
--        when it is ALREADY installed (never created here); opening the timeline also self-heals that one quote.
--
-- SAFETY (zero data loss / no behaviour change):
--   * No existing table, column, row, function, trigger or policy is changed or deleted. New tables use the column
--     name quote_ref (NOT quote_id) and have no foreign key to quotes ON PURPOSE: the empty-draft cleanup (0141 /
--     0220) and the tenant guards (0004 / 0136) scan every quote_id column / FK at run time - a stage row must never
--     make an empty draft look "used". Tenancy: org_id is always copied from the quote row by the trigger itself.
--   * Every trigger body runs inside its own exception block: if logging ever fails, the original write still
--     commits (a WARNING is raised). Only ENFORCE mode (off by default) can refuse a write, and only a studio user's.
--   * The quotes trigger fires only when one of the state columns changes (pricing autosaves never run it).
--   * Trial retention (0184, owner switch, off by default) empties the four new studio tables with the rest of an
--     expired trial's events (patched in place, once).
-- Additive + idempotent: safe to run twice (the 2nd run changes nothing). ASCII only.
-- ROLLBACK (manual, only if ever needed - the switch is simpler: HQ -> Stage tracking OFF):
--   drop trigger if exists zz_r23_stage on public.quotes; drop trigger if exists zz_r23_stage_upd on public.quotes;
--   drop trigger if exists zzzzzz_r23_stage_guard on public.quotes; drop trigger if exists zz_r23_stage on public.event_closure;
--   drop trigger if exists zz_r23_stage on public.client_link_opens;  (the new tables can stay, unused)

-- ---- 0) prechecks ---------------------------------------------------------------------------------------------
do $$ declare c text; begin
  foreach c in array array['status', 'approval_status', 'lifecycle_stage', 'archived_at', 'archived_reason', 'deleted_at',
                           'deleted_reason', 'link_expired_at', 'approval_token_expires_at', 'consent_stale', 'org_id'] loop
    if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quotes' and column_name = c) then
      raise exception 'STOP 0263: quotes.% is missing (apply 0040 / 0052 / 0208 first)', c; end if;
  end loop;
  if to_regclass('public.event_closure') is null or to_regclass('public.client_link_opens') is null then
    raise exception 'STOP 0263: event_closure / client_link_opens missing (apply 0049 + 0078 first)'; end if;
  if to_regprocedure('public.has_area(text,text)') is null or to_regprocedure('public.current_org_id()') is null
     or to_regprocedure('public.user_role()') is null or to_regprocedure('public.is_platform_admin()') is null then
    raise exception 'STOP 0263: has_area / current_org_id / user_role / is_platform_admin missing'; end if;
  if to_regprocedure('public._hq_wgate(text,text,text,jsonb)') is null then
    raise exception 'STOP 0263: _hq_wgate missing (apply 0045 first)'; end if;
  if to_regclass('public.app_config') is null then raise exception 'STOP 0263: app_config missing'; end if;
end $$;

-- ---- 1) the ONE stage rule (pure) -----------------------------------------------------------------------------
-- p_shelf: null (in the normal lists) | 'expired' (shelved because the client link ran out) | 'lost' (archived /
-- deleted by hand or as an empty draft). p_viewed: the client opened the approval link. p_token_expired: the
-- approval link's expiry time has passed.
--   cancelled      status = 'cancelled' (cancel_event)                           - always wins
--   closed         lifecycle 'closed' or event_closure.closed_at set
--   completed      lifecycle 'settlement' (the event is over, money being settled)
--   event_day      lifecycle 'event_day'
--   in_progress    lifecycle planning / resources / ready
--   (lifecycle lead .. confirmed from here on)
--   confirmed      approval 'paid' at lifecycle 'confirmed' (approved + advance in = booked), or the studio moved it to
--                  Confirmed without an online approval (lifecycle 'confirmed', no approval, no stale price)
--   advance_paid   approval 'paid' before lifecycle 'confirmed'
--   approved       approval 'approved' (client approved, advance pending)
--   expired/lost   the quote is on a shelf (only while not approved / paid)
--   expired        approval 'sent' and the link's expiry has passed
--   viewed         approval 'sent' and the client opened the link
--   sent           approval 'sent' (or a price change after approval is waiting for the client again)
--   lead           lifecycle lead / discovery, nothing sent
--   draft          everything else (incl. priced + locked but not sent)
create or replace function public.helm_quote_stage(p_status text, p_approval text, p_lifecycle text, p_closed boolean,
                                                  p_viewed boolean, p_stale boolean, p_shelf text, p_token_expired boolean)
returns text language sql immutable set search_path = '' as $$
  -- helm-0263-stage-rule (mirrored line for line by BPStore.quoteStage in store-api.js)
  select case
    when coalesce(p_status, '') = 'cancelled' then 'cancelled'
    when coalesce(nullif(p_lifecycle, ''), 'quote') = 'closed' or coalesce(p_closed, false) then 'closed'
    when p_lifecycle = 'settlement' then 'completed'
    when p_lifecycle = 'event_day' then 'event_day'
    when p_lifecycle in ('planning', 'resources', 'ready') then 'in_progress'
    when coalesce(p_approval, '') = 'paid' and p_lifecycle = 'confirmed' then 'confirmed'
    when coalesce(p_approval, '') = 'paid' then 'advance_paid'
    when coalesce(p_approval, '') = 'approved' and not coalesce(p_stale, false) then 'approved'
    when p_lifecycle = 'confirmed' and not (coalesce(p_stale, false) and coalesce(p_approval, '') in ('sent', 'approved')) then 'confirmed'
    when p_shelf in ('expired', 'lost') then p_shelf
    when coalesce(p_approval, '') in ('sent', 'approved') and coalesce(p_token_expired, false) then 'expired'
    when coalesce(p_approval, '') in ('sent', 'approved') and coalesce(p_viewed, false) then 'viewed'
    when coalesce(p_approval, '') in ('sent', 'approved') then 'sent'
    when p_lifecycle in ('lead', 'discovery') then 'lead'
    else 'draft'
  end
$$;

create or replace function public.helm_quote_stage_label(p_stage text)
returns text language sql immutable set search_path = '' as $$
  -- helm-0263-stage-rule
  select case p_stage
    when 'lead' then 'Lead' when 'draft' then 'Draft' when 'sent' then 'Sent' when 'viewed' then 'Viewed by client'
    when 'approved' then 'Approved' when 'advance_paid' then 'Advance paid' when 'confirmed' then 'Confirmed'
    when 'in_progress' then 'In progress' when 'event_day' then 'Event day' when 'completed' then 'Completed'
    when 'closed' then 'Closed' when 'cancelled' then 'Cancelled' when 'expired' then 'Expired' when 'lost' then 'Lost'
    else coalesce(p_stage, '') end
$$;

-- position on the path (side stages sit next to where they branch off); used for ordering + the HQ view
create or replace function public.helm_quote_stage_order(p_stage text)
returns integer language sql immutable set search_path = '' as $$
  -- helm-0263-stage-rule
  select case p_stage
    when 'lead' then 10 when 'draft' then 20 when 'sent' then 30 when 'viewed' then 40 when 'expired' then 45
    when 'lost' then 46 when 'approved' then 50 when 'advance_paid' then 60 when 'confirmed' then 70
    when 'in_progress' then 80 when 'event_day' then 90 when 'completed' then 100 when 'closed' then 110
    when 'cancelled' then 120 else null end
$$;

-- ---- 2) tables --------------------------------------------------------------------------------------------------
-- NOTE: quote_ref, not quote_id, and no FK to quotes - see SAFETY above (0141 / 0220 / 0004 / 0136 scans).
create table if not exists public.quote_stage_transitions (
  id          bigserial primary key,
  org_id      uuid not null,
  quote_ref   uuid not null,
  from_stage  text,
  to_stage    text not null,
  actor       uuid,
  actor_email text,
  actor_role  text,
  source      text not null check (source in ('ui', 'rpc', 'client', 'cron', 'system', 'backfill')),
  via         text,
  reason      text,
  legal       boolean not null default true,
  detail      jsonb not null default '{}'::jsonb,
  xact        bigint not null default txid_current(),   -- the writing transaction (one move per transaction, see 5)
  at          timestamptz not null default now()
);
create index if not exists quote_stage_transitions_quote_idx on public.quote_stage_transitions(org_id, quote_ref, at desc, id desc);
create index if not exists quote_stage_transitions_at_idx on public.quote_stage_transitions(at desc);

create table if not exists public.quote_stage_current (
  quote_ref          uuid primary key,
  org_id             uuid not null,
  stage              text not null,
  since              timestamptz not null default now(),
  last_transition_id bigint,
  updated_at         timestamptz not null default now()
);
create index if not exists quote_stage_current_org_idx on public.quote_stage_current(org_id, stage);

create table if not exists public.quote_stage_warnings (
  id         bigserial primary key,
  org_id     uuid not null,
  quote_ref  uuid not null,
  from_stage text,
  to_stage   text not null,
  mode       text not null default 'warn',
  source     text,
  via        text,
  actor      uuid,
  xact       bigint not null default txid_current(),
  at         timestamptz not null default now()
);
create index if not exists quote_stage_warnings_at_idx on public.quote_stage_warnings(at desc);
create index if not exists quote_stage_warnings_org_idx on public.quote_stage_warnings(org_id, at desc);

-- the allowed moves (from -> to). Seeded once below; rows are never deleted by Helm. A move that is not here is an
-- "illegal move" (logged in WARN mode, refused for studio users in ENFORCE mode).
create table if not exists public.quote_stage_moves (
  from_stage text not null,
  to_stage   text not null,
  note       text,
  created_at timestamptz not null default now(),
  primary key (from_stage, to_stage)
);

-- domain events: one row per business event, read in order by automations (see domain_events_pull)
create table if not exists public.domain_events (
  id          bigserial primary key,
  org_id      uuid not null,
  type        text not null check (type ~ '^[a-z_]+\.[a-z_]+$'),
  entity_type text not null default 'quote',
  entity_ref  uuid,
  actor       uuid,
  source      text,
  payload     jsonb not null default '{}'::jsonb,
  xact        bigint not null default txid_current(),
  created_at  timestamptz not null default now()
);
create index if not exists domain_events_org_idx on public.domain_events(org_id, id desc);
create index if not exists domain_events_type_idx on public.domain_events(type, id);
create index if not exists domain_events_entity_idx on public.domain_events(entity_type, entity_ref, id desc);

create table if not exists public.domain_event_cursors (
  consumer   text primary key check (consumer ~ '^[a-z0-9_.-]{2,60}$'),
  last_id    bigint not null default 0,
  updated_at timestamptz not null default now()
);

-- HQ switches (one row). tracking_enabled = the kill switch; guard_mode off / warn / enforce; emit_events.
create table if not exists public.helm_stage_settings (
  id               boolean primary key default true check (id),
  tracking_enabled boolean not null default true,
  guard_mode       text not null default 'warn' check (guard_mode in ('off', 'warn', 'enforce')),
  emit_events      boolean not null default true,
  updated_at       timestamptz not null default now(),
  updated_by       uuid
);
insert into public.helm_stage_settings(id) values (true) on conflict (id) do nothing;

-- RLS + grants: the app only READS (own studio, quotes view); every write goes through the definer functions.
do $$ declare t text; begin
  foreach t in array array['quote_stage_transitions', 'quote_stage_current', 'quote_stage_warnings', 'quote_stage_moves',
                           'domain_events', 'domain_event_cursors', 'helm_stage_settings'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on public.%I from anon', t); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on public.%I from authenticated', t); end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant all on public.%I to service_role', t); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select on public.quote_stage_transitions, public.quote_stage_current, public.quote_stage_moves, public.domain_events to authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant usage, select on sequence public.quote_stage_transitions_id_seq, public.quote_stage_warnings_id_seq, public.domain_events_id_seq to service_role';
  end if;
end $$;

drop policy if exists "r23 stage transitions read" on public.quote_stage_transitions;
create policy "r23 stage transitions read" on public.quote_stage_transitions for select to authenticated
  using (org_id = (select public.current_org_id()) and public.has_area('quotes', 'view'));
drop policy if exists "r23 stage current read" on public.quote_stage_current;
create policy "r23 stage current read" on public.quote_stage_current for select to authenticated
  using (org_id = (select public.current_org_id()) and public.has_area('quotes', 'view'));
drop policy if exists "r23 stage moves read" on public.quote_stage_moves;
create policy "r23 stage moves read" on public.quote_stage_moves for select to authenticated using (true);
drop policy if exists "r23 domain events read" on public.domain_events;
create policy "r23 domain events read" on public.domain_events for select to authenticated
  using (org_id = (select public.current_org_id()) and public.has_area('quotes', 'view'));

-- append-only: a transition / domain event row is never rewritten (deleting stays possible ONLY for the owner-run
-- trial retention purge, which runs without API grants)
create or replace function public.tg_r23_append_only()
returns trigger language plpgsql set search_path = '' as $$
begin
  raise exception '% rows are append-only', tg_table_name using errcode = '42501';
end $$;
revoke all on function public.tg_r23_append_only() from public;
drop trigger if exists zz_r23_append_only on public.quote_stage_transitions;
create trigger zz_r23_append_only before update on public.quote_stage_transitions
  for each row execute function public.tg_r23_append_only();
drop trigger if exists zz_r23_append_only on public.domain_events;
create trigger zz_r23_append_only before update on public.domain_events
  for each row execute function public.tg_r23_append_only();

-- ---- 3) allowed moves (seed, insert-only) --------------------------------------------------------------------
do $$ declare
  v_path text[] := array['lead', 'draft', 'sent', 'viewed', 'approved', 'advance_paid', 'confirmed', 'in_progress',
                         'event_day', 'completed', 'closed'];
  v_booked text[] := array['approved', 'advance_paid', 'confirmed', 'in_progress', 'event_day', 'completed'];
  i int; j int; a text; b text;
begin
  -- every forward move along the path (skipping stages is fine, like a CRM pipeline)
  for i in 1 .. array_length(v_path, 1) loop
    for j in i + 1 .. array_length(v_path, 1) loop
      insert into public.quote_stage_moves(from_stage, to_stage, note) values (v_path[i], v_path[j], 'forward')
        on conflict do nothing;
    end loop;
  end loop;
  -- once booked, the stage can move back and forth (set_lifecycle_stage allows backward moves from Confirmed on)
  foreach a in array v_booked loop
    foreach b in array v_booked loop
      if a <> b then insert into public.quote_stage_moves(from_stage, to_stage, note) values (a, b, 'booked: back / forth')
        on conflict do nothing; end if;
    end loop;
  end loop;
  -- before the client approves: edit again, re-send, re-approval after a price change, offline approval
  insert into public.quote_stage_moves(from_stage, to_stage, note) values
    ('draft', 'lead', 'back to enquiry'), ('sent', 'draft', 'link withdrawn / edited'), ('sent', 'lead', 'link withdrawn'),
    ('viewed', 'sent', 'link re-issued'), ('viewed', 'draft', 'link withdrawn / edited'), ('viewed', 'lead', 'link withdrawn'),
    ('approved', 'sent', 'price changed - client must approve again'), ('approved', 'viewed', 'price changed - client must approve again'),
    ('approved', 'draft', 'approval withdrawn'),
    ('confirmed', 'sent', 'price changed - client must approve again'), ('confirmed', 'viewed', 'price changed - client must approve again'),
    ('in_progress', 'sent', 'price changed - client must approve again'),
    -- link ran out (0039 / 0040) / shelved / restored
    ('sent', 'expired', 'client link ran out'), ('viewed', 'expired', 'client link ran out'), ('approved', 'expired', 'client link ran out'),
    ('expired', 'sent', 'link re-issued'), ('expired', 'viewed', 'link re-issued'), ('expired', 'draft', 'restored'),
    ('expired', 'lead', 'restored'), ('expired', 'approved', 'link re-issued and approved'), ('expired', 'lost', 'shelved'),
    ('expired', 'advance_paid', 'paid after re-issue'), ('expired', 'confirmed', 'confirmed by the studio'),
    ('lead', 'lost', 'archived / deleted'), ('draft', 'lost', 'archived / deleted'), ('sent', 'lost', 'archived / deleted'),
    ('viewed', 'lost', 'archived / deleted'), ('lead', 'expired', 'shelved: link ran out'), ('draft', 'expired', 'shelved: link ran out'),
    ('lost', 'lead', 'restored'), ('lost', 'draft', 'restored'), ('lost', 'sent', 'restored'), ('lost', 'viewed', 'restored'),
    ('lost', 'expired', 'restored'), ('lost', 'approved', 'restored'), ('lost', 'confirmed', 'restored'),
    -- closing / re-opening / cancelling (0049 / 0084 / 0152 / 0198)
    ('closed', 'completed', 're-opened (reopen_event)'), ('cancelled', 'closed', 'a cancelled event settled and closed'),
    ('expired', 'cancelled', 'cancelled'), ('lost', 'cancelled', 'cancelled'),
    ('expired', 'closed', 'closed'), ('lost', 'closed', 'closed')
  on conflict do nothing;
  foreach a in array array['lead', 'draft', 'sent', 'viewed', 'approved', 'advance_paid', 'confirmed', 'in_progress', 'event_day', 'completed'] loop
    insert into public.quote_stage_moves(from_stage, to_stage, note) values (a, 'cancelled', 'cancelled') on conflict do nothing;
  end loop;
end $$;

create or replace function public.quote_stage_allowed(p_from text, p_to text)
returns boolean language sql stable security definer set search_path = '' as $$
  -- helm-0263-stage-machine: a first stage (no from) and staying put are always allowed
  select p_from is null or p_from = p_to
      or exists (select 1 from public.quote_stage_moves m where m.from_stage = p_from and m.to_stage = p_to);
$$;

-- ---- 4) live stage of one quote + who / how / why ------------------------------------------------------------------
create or replace function public._r23_quote_stage_now(p_quote uuid)
returns text language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare q record; v_closed boolean; v_viewed boolean; v_shelf text;
begin
  select x.status, x.approval_status, x.lifecycle_stage, x.consent_stale, x.archived_at, x.archived_reason,
         x.deleted_at, x.deleted_reason, x.link_expired_at, x.approval_token_expires_at
    into q from public.quotes x where x.id = p_quote;
  if not found then return null; end if;
  v_closed := exists (select 1 from public.event_closure c where c.quote_id = p_quote and c.closed_at is not null);
  v_viewed := exists (select 1 from public.client_link_opens o where o.quote_id = p_quote and o.kind = 'quote');
  if q.archived_at is not null or q.deleted_at is not null then
    v_shelf := case when coalesce(q.deleted_reason, q.archived_reason) = 'link_expired' or q.link_expired_at is not null
                    then 'expired' else 'lost' end;
  end if;
  return public.helm_quote_stage(q.status, q.approval_status, q.lifecycle_stage, v_closed, v_viewed, q.consent_stale,
                                 v_shelf, q.approval_token_expires_at is not null and q.approval_token_expires_at <= now());
end $$;

-- how the change reached the database: client link (anon / client portal), a studio user's RPC or direct save,
-- a service-role edge function / webhook, pg_cron, or SQL run by hand. An RPC may name itself with
-- set_config('helm.stage_source', 'rpc', true) / set_config('helm.stage_reason', '...', true).
create or replace function public._r23_source()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v_claims jsonb; v_role text; v_path text; v_via text; v_src text; v_prole text;
begin
  begin v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb; exception when others then v_claims := null; end;
  v_role := coalesce(v_claims ->> 'role', '');
  v_path := nullif(current_setting('request.path', true), '');
  if v_path like '/rpc/%' then v_via := left(substr(v_path, 6), 80); end if;
  v_src := nullif(current_setting('helm.stage_source', true), '');
  if v_src is not null and v_src not in ('ui', 'rpc', 'client', 'cron', 'system') then v_src := null; end if;
  if v_role = 'authenticated' and (v_claims ->> 'sub') ~* '^[0-9a-f-]{36}$' then
    select p.role into v_prole from public.profiles p where p.id = (v_claims ->> 'sub')::uuid;
  end if;
  if v_src is null then
    v_src := case
      when v_role = 'anon' then 'client'
      when v_role = 'authenticated' and v_prole = 'client' then 'client'
      when v_role = 'authenticated' then case when v_via is not null then 'rpc' else 'ui' end
      when v_role = 'service_role' then 'system'
      when coalesce(current_setting('application_name', true), '') ilike 'pg_cron%' then 'cron'
      else 'system' end;
  end if;
  return jsonb_build_object('source', v_src, 'via', v_via, 'role', nullif(v_role, ''), 'profile_role', v_prole,
    'actor', case when v_role in ('authenticated', 'service_role') and (v_claims ->> 'sub') ~* '^[0-9a-f-]{36}$'
                  then v_claims ->> 'sub' end);
end $$;

-- the reason given in the same transaction as a move (cancel / stage override / close override / reopen ...), if any.
-- p_at = that transaction's time (now() while it runs; a stored move's "at" later - rows written in one transaction
-- all carry the same now(), so a reason saved AFTER the stage changed is still found when the history is read).
create or replace function public._r23_reason(p_quote uuid, p_at timestamptz default now())
returns text language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v text;
begin
  if p_quote is null or p_at is null then return null; end if;
  if p_at = now() then
    v := nullif(btrim(coalesce(current_setting('helm.stage_reason', true), '')), '');
    if v is not null then return left(v, 1000); end if;
  end if;
  begin
    select c.reason into v from public.event_cancellations c where c.quote_id = p_quote and c.created_at = p_at
     order by c.created_at desc limit 1;
    if v is null then
      select o.reason into v from public.lifecycle_stage_overrides o where o.quote_id = p_quote and o.created_at = p_at
       order by o.created_at desc limit 1;
    end if;
    if v is null then
      select o.reason into v from public.event_close_overrides o where o.quote_id = p_quote and o.created_at = p_at
       order by o.created_at desc limit 1;
    end if;
    if v is null then
      select a.changed ->> 'reason' into v from public.audit_log a
       where a.quote_id = p_quote and a.at = p_at and jsonb_typeof(a.changed -> 'reason') = 'string'
       order by a.id desc limit 1;
    end if;
  exception when others then v := null;   -- an older database without one of those tables
  end;
  return left(nullif(btrim(coalesce(v, '')), ''), 1000);
end $$;

-- the guard mode for one studio: HQ off / enforce win; HQ warn -> the studio's own Control Center choice
create or replace function public._r23_guard_mode(p_org uuid)
returns text language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v_hq text; v_st text;
begin
  select s.guard_mode into v_hq from public.helm_stage_settings s where s.id;
  v_hq := coalesce(v_hq, 'warn');
  if v_hq in ('off', 'enforce') then return v_hq; end if;
  select c.value ->> 'guardMode' into v_st from public.app_config c where c.org_id = p_org and c.key = 'stage_machine';
  return case when v_st = 'enforce' then 'enforce' else 'warn' end;
end $$;

-- ---- 5) record a move (the ONE writer) -----------------------------------------------------------------------------
-- p_mode: 'trigger' (a write changed the quote / its closure / the client opened the link), 'heal' (a read found the
-- stored stage behind - e.g. a link that ran out), 'sweep' (the 30-minute job). Returns the new stage or null.
-- ONE MOVE PER TRANSACTION: when the same transaction already recorded a move for this quote (an RPC that sets
-- approval, then lifecycle, then status one after the other), that provisional row is replaced, so the history shows
-- "viewed -> approved", never the in-between steps. The rows replaced are only this transaction's own, never a
-- committed one.
create or replace function public._r23_stage_sync(p_quote uuid, p_mode text default 'trigger')
returns text language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare
  v_set record; v_org uuid; v_new text; v_cur record; v_own record; v_prev record; v_from text; v_src jsonb; v_source text;
  v_actor uuid; v_email text; v_legal boolean; v_gmode text; v_tid bigint; v_reason text; v_detail jsonb; q record;
  v_x bigint := txid_current(); v_mine boolean := false; v_had boolean;
begin
  if p_quote is null then return null; end if;
  select s.tracking_enabled, s.emit_events, s.guard_mode into v_set from public.helm_stage_settings s where s.id;
  if found and not v_set.tracking_enabled then return null; end if;
  select x.org_id, x.status, x.approval_status, x.lifecycle_stage into q from public.quotes x where x.id = p_quote;
  if not found or q.org_id is null then return null; end if;
  v_org := q.org_id;
  v_new := public._r23_quote_stage_now(p_quote);
  if v_new is null then return null; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:stage:' || p_quote::text, 0));
  select c.stage, c.since, c.last_transition_id into v_cur from public.quote_stage_current c where c.quote_ref = p_quote for update;
  v_had := found;
  if v_had and v_cur.stage = v_new then return null; end if;
  v_from := v_cur.stage;
  if v_had and v_cur.last_transition_id is not null then
    select t.id, t.from_stage, t.xact into v_own from public.quote_stage_transitions t where t.id = v_cur.last_transition_id;
    v_mine := found and v_own.xact = v_x;
  end if;
  if v_mine then
    -- this transaction's own provisional move: drop it (and its warning / event), keep the stage it started from
    delete from public.domain_events e where e.xact = v_x and e.entity_ref = p_quote;
    delete from public.quote_stage_warnings w where w.xact = v_x and w.quote_ref = p_quote;
    delete from public.quote_stage_transitions t where t.id = v_own.id and t.xact = v_x;
    v_from := v_own.from_stage;
    if v_from is not distinct from v_new then                      -- back where the transaction started: no move
      select t.id, t.at into v_prev from public.quote_stage_transitions t where t.quote_ref = p_quote order by t.id desc limit 1;
      update public.quote_stage_current c set stage = v_new, since = coalesce(v_prev.at, c.since),
             last_transition_id = v_prev.id, updated_at = now() where c.quote_ref = p_quote;
      return null;
    end if;
  end if;

  v_src := public._r23_source();
  v_source := case when p_mode = 'sweep' then 'cron' when p_mode = 'heal' then 'system' else v_src ->> 'source' end;
  if (v_src ->> 'actor') is not null then v_actor := (v_src ->> 'actor')::uuid; end if;
  v_legal := public.quote_stage_allowed(v_from, v_new);
  if not v_legal then
    v_gmode := public._r23_guard_mode(v_org);
    if v_gmode <> 'off' then
      insert into public.quote_stage_warnings(org_id, quote_ref, from_stage, to_stage, mode, source, via, actor)
        values (v_org, p_quote, v_from, v_new, v_gmode, v_source, v_src ->> 'via', v_actor);
    end if;
  end if;
  if v_actor is not null then select u.email into v_email from auth.users u where u.id = v_actor; end if;
  v_reason := public._r23_reason(p_quote);
  v_detail := jsonb_strip_nulls(jsonb_build_object('status', q.status, 'approval_status', q.approval_status,
                'lifecycle_stage', q.lifecycle_stage, 'mode', nullif(p_mode, 'trigger')));
  insert into public.quote_stage_transitions(org_id, quote_ref, from_stage, to_stage, actor, actor_email, actor_role,
                                             source, via, reason, legal, detail)
    values (v_org, p_quote, v_from, v_new, v_actor, v_email, v_src ->> 'profile_role', v_source, v_src ->> 'via',
            v_reason, v_legal, v_detail)
    returning id into v_tid;
  insert into public.quote_stage_current(quote_ref, org_id, stage, since, last_transition_id, updated_at)
    values (p_quote, v_org, v_new, now(), v_tid, now())
  on conflict (quote_ref) do update set org_id = excluded.org_id, stage = excluded.stage, since = excluded.since,
    last_transition_id = excluded.last_transition_id, updated_at = excluded.updated_at;
  if coalesce(v_set.emit_events, true) then
    insert into public.domain_events(org_id, type, entity_type, entity_ref, actor, source, payload)
      values (v_org, 'quote.' || v_new, 'quote', p_quote, v_actor, v_source,
              jsonb_strip_nulls(jsonb_build_object('from', v_from, 'to', v_new, 'transition_id', v_tid,
                'legal', v_legal, 'via', v_src ->> 'via')));
  end if;
  return v_new;
end $$;

-- ---- 6) the triggers --------------------------------------------------------------------------------------------------------
-- (a) RECORD: plain AFTER ROW triggers (fire at the end of each statement - nothing is left pending, so a later
--     ALTER TABLE in the same transaction is never blocked). The body runs in its own exception block: if logging ever
--     fails the original write still goes through (a WARNING is raised) and the next read heals the stage.
create or replace function public.tg_r23_stage()
returns trigger language plpgsql security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v_q uuid;
begin
  begin
    if tg_table_name = 'quotes' then v_q := new.id; else v_q := new.quote_id; end if;   -- separate statements: each row type has its own column
    perform public._r23_stage_sync(v_q, 'trigger');
  exception when others then
    raise warning 'helm 0263: stage not recorded for % (%)', v_q, sqlerrm;
  end;
  return null;
end $$;
revoke all on function public.tg_r23_stage() from public;

-- a new quote records its first stage; an UPDATE runs the trigger only when a state column changed
drop trigger if exists zz_r23_stage on public.quotes;
create trigger zz_r23_stage after insert on public.quotes for each row execute function public.tg_r23_stage();
drop trigger if exists zz_r23_stage_upd on public.quotes;
create trigger zz_r23_stage_upd after update on public.quotes for each row
  when (old.status is distinct from new.status or old.approval_status is distinct from new.approval_status
        or old.lifecycle_stage is distinct from new.lifecycle_stage or old.consent_stale is distinct from new.consent_stale
        or old.archived_at is distinct from new.archived_at or old.deleted_at is distinct from new.deleted_at
        or old.archived_reason is distinct from new.archived_reason or old.deleted_reason is distinct from new.deleted_reason
        or old.link_expired_at is distinct from new.link_expired_at
        or old.approval_token_expires_at is distinct from new.approval_token_expires_at
        or old.org_id is distinct from new.org_id)
  execute function public.tg_r23_stage();
drop trigger if exists zz_r23_stage on public.event_closure;
create trigger zz_r23_stage after insert or update on public.event_closure for each row execute function public.tg_r23_stage();
drop trigger if exists zz_r23_stage on public.client_link_opens;
create trigger zz_r23_stage after insert on public.client_link_opens for each row when (new.kind = 'quote')
  execute function public.tg_r23_stage();

-- (b) ENFORCE: a DEFERRED check at COMMIT (so it judges the transaction's final move, not an in-between step).
--     Queued ONLY while some studio (or HQ) has ENFORCE on - in the default WARN mode nothing is queued at all.
--     Refuses (HL423) only a move recorded as 'ui' / 'rpc' (a signed-in studio user); client links, service-role
--     webhooks, cron and SQL-editor work are never refused (they are logged as warnings).
create or replace function public._r23_enforcing()
returns boolean language sql stable security definer set search_path = '' as $$
  -- helm-0263-stage-machine: is ENFORCE on anywhere? (cheap: one settings row + the few 'stage_machine' config rows)
  select coalesce((select s.tracking_enabled and s.guard_mode <> 'off'
                          and (s.guard_mode = 'enforce'
                               or exists (select 1 from public.app_config c where c.key = 'stage_machine' and c.value ->> 'guardMode' = 'enforce'))
                     from public.helm_stage_settings s where s.id), false);
$$;
revoke all on function public._r23_enforcing() from public;
-- the trigger's WHEN runs as whoever writes the quote (a studio user's save, a client link, a webhook), so every API
-- role may call it; it only answers "is ENFORCE on anywhere" (true / false), nothing else
do $$ declare r text; begin
  foreach r in array array['anon', 'authenticated', 'service_role'] loop
    if exists (select 1 from pg_roles where rolname = r) then execute format('grant execute on function public._r23_enforcing() to %I', r); end if;
  end loop;
end $$;

create or replace function public.tg_r23_stage_guard()
returns trigger language plpgsql security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare t record;
begin
  select x.from_stage, x.to_stage, x.source, x.legal, x.org_id into t
    from public.quote_stage_current c join public.quote_stage_transitions x on x.id = c.last_transition_id
   where c.quote_ref = new.id and x.xact = txid_current();
  if not found or t.legal or t.source not in ('ui', 'rpc') then return null; end if;
  if public._r23_guard_mode(t.org_id) <> 'enforce' then return null; end if;
  raise exception 'This move is not allowed: % -> %.', public.helm_quote_stage_label(t.from_stage), public.helm_quote_stage_label(t.to_stage)
    using errcode = 'HL423', hint = 'Stage rules are enforced for this studio. Ask an admin, or use the event''s own actions.';
end $$;
revoke all on function public.tg_r23_stage_guard() from public;
drop trigger if exists zzzzzz_r23_stage_guard on public.quotes;
create constraint trigger zzzzzz_r23_stage_guard after update on public.quotes
  deferrable initially deferred for each row
  when ((old.status is distinct from new.status or old.approval_status is distinct from new.approval_status
         or old.lifecycle_stage is distinct from new.lifecycle_stage or old.archived_at is distinct from new.archived_at
         or old.deleted_at is distinct from new.deleted_at or old.consent_stale is distinct from new.consent_stale)
        and public._r23_enforcing())
  execute function public.tg_r23_stage_guard();

-- ---- 7) the canonical stage view (RLS of quotes + the stage table applies: security_invoker) --------------------------
create or replace view public.quote_stage_v with (security_invoker = true) as
  select q.id as quote_ref, q.org_id, c.stage, public.helm_quote_stage_label(c.stage) as stage_label,
         public.helm_quote_stage_order(c.stage) as stage_order, c.since
    from public.quotes q join public.quote_stage_current c on c.quote_ref = q.id;
revoke all on public.quote_stage_v from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on public.quote_stage_v from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'grant select on public.quote_stage_v to authenticated'; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant select on public.quote_stage_v to service_role'; end if;
end $$;

-- ---- 8) read RPCs for the app ----------------------------------------------------------------------------------------
-- the event workspace / quote flow timeline. Same studio + quotes view; never for a client portal user.
create or replace function public.quote_stage_history(p_quote uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v_org uuid := public.current_org_id(); c record; v_rows jsonb; v_show boolean := true; v_cfg jsonb;
begin
  if auth.uid() is null or v_org is null or coalesce(public.user_role(), '') = 'client' or not public.has_area('quotes', 'view') then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if not exists (select 1 from public.quotes q where q.id = p_quote and q.org_id = v_org) then
    raise exception 'not authorized for this event' using errcode = '42501'; end if;
  begin perform public._r23_stage_sync(p_quote, 'heal'); exception when others then null; end;   -- self-heal, never fails the read
  select x.stage, x.since into c from public.quote_stage_current x where x.quote_ref = p_quote and x.org_id = v_org;
  select a.value into v_cfg from public.app_config a where a.org_id = v_org and a.key = 'stage_machine';
  if jsonb_typeof(v_cfg -> 'showHistory') = 'boolean' then v_show := (v_cfg ->> 'showHistory')::boolean; end if;
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'id', t.id, 'from', t.from_stage, 'to', t.to_stage,
           'from_label', public.helm_quote_stage_label(t.from_stage), 'to_label', public.helm_quote_stage_label(t.to_stage),
           'at', t.at, 'source', t.source, 'via', t.via, 'legal', t.legal,
           'reason', coalesce(t.reason, case when t.source <> 'backfill' then public._r23_reason(t.quote_ref, t.at) end),
           'actor_name', case when t.source = 'client' then null
                              else coalesce(nullif(btrim(p.full_name), ''), nullif(split_part(coalesce(t.actor_email, p.email, ''), '@', 1), '')) end,
           'actor_role', t.actor_role)) order by t.at desc, t.id desc), '[]'::jsonb)
    into v_rows
    from (select * from public.quote_stage_transitions t2 where t2.org_id = v_org and t2.quote_ref = p_quote
           order by t2.at desc, t2.id desc limit 200) t
    left join public.profiles p on p.id = t.actor and p.org_id = v_org;
  return jsonb_build_object('quote_id', p_quote, 'stage', c.stage, 'label', public.helm_quote_stage_label(c.stage),
    'since', c.since, 'show_history', v_show, 'history', v_rows);
end $$;

-- stage pills for many quotes at once (own studio only; at most 500 ids)
create or replace function public.quote_stage_list(p_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v_org uuid := public.current_org_id();
begin
  if auth.uid() is null or v_org is null or coalesce(public.user_role(), '') = 'client' or not public.has_area('quotes', 'view') then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if coalesce(cardinality(p_ids), 0) > 500 then raise exception 'at most 500 quotes at once' using errcode = '22023'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('quote_id', c.quote_ref, 'stage', c.stage,
            'label', public.helm_quote_stage_label(c.stage), 'since', c.since)), '[]'::jsonb)
            from public.quote_stage_current c where c.org_id = v_org and c.quote_ref = any(coalesce(p_ids, '{}'::uuid[])));
end $$;

-- ---- 9) settings: Control Center (studio) + HQ ---------------------------------------------------------------------------
create or replace function public.stage_machine_settings()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare v_org uuid := public.current_org_id(); v jsonb; s record; v_at timestamptz;
begin
  if auth.uid() is null or v_org is null or coalesce(public.user_role(), '') = 'client' then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if not (public.has_area('controls', 'view') or public.has_area('quotes', 'view')) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  select c.value, c.updated_at into v, v_at from public.app_config c where c.org_id = v_org and c.key = 'stage_machine';
  select x.tracking_enabled, x.guard_mode into s from public.helm_stage_settings x where x.id;
  return jsonb_build_object(
    'guard_mode', case when v ->> 'guardMode' = 'enforce' then 'enforce' else 'warn' end,
    'show_history', case when jsonb_typeof(v -> 'showHistory') = 'boolean' then (v ->> 'showHistory')::boolean else true end,
    'hq_guard_mode', coalesce(s.guard_mode, 'warn'), 'tracking', coalesce(s.tracking_enabled, true),
    'effective_mode', public._r23_guard_mode(v_org),
    'warnings_30d', (select count(*) from public.quote_stage_warnings w where w.org_id = v_org and w.at > now() - interval '30 days'),
    'can_edit', public.has_area('controls', 'edit') and coalesce(public.user_role(), '') = 'admin',
    'updated_at', v_at);
end $$;

create or replace function public.set_stage_machine_settings(p_guard_mode text, p_show_history boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-stage-machine: studio ADMIN with Control Center edit; merged into the app_config row (other keys kept)
declare v_org uuid := public.current_org_id(); v_patch jsonb := '{}'::jsonb;
begin
  if auth.uid() is null or v_org is null or coalesce(public.user_role(), '') <> 'admin' or not public.has_area('controls', 'edit') then
    raise exception 'Only a studio admin can change the stage rules.' using errcode = '42501'; end if;
  if p_guard_mode is not null then
    if p_guard_mode not in ('warn', 'enforce') then raise exception 'Stage rules must be warn or enforce.' using errcode = '22023'; end if;
    v_patch := v_patch || jsonb_build_object('guardMode', p_guard_mode);
  end if;
  if p_show_history is not null then v_patch := v_patch || jsonb_build_object('showHistory', p_show_history); end if;
  insert into public.app_config(org_id, key, value, updated_at) values (v_org, 'stage_machine', v_patch, now())
  on conflict (org_id, key) do update
    set value = (case when jsonb_typeof(public.app_config.value) = 'object' then public.app_config.value else '{}'::jsonb end) || v_patch,
        updated_at = now();
  insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id)
    values (auth.uid(), (select u.email from auth.users u where u.id = auth.uid()), 'stage_machine.settings', 'app_config',
            'stage_machine', v_patch, v_org);
  return public.stage_machine_settings();
end $$;

-- HQ: switches + platform-wide COUNTS only (no studio names, no quote data - 0045 rule)
create or replace function public.hq_stage_machine()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare s record; v_pairs jsonb;
begin
  if not public.is_platform_admin() then raise exception 'not authorized' using errcode = '42501'; end if;
  select x.* into s from public.helm_stage_settings x where x.id;
  select coalesce(jsonb_agg(jsonb_build_object('from', f, 'to', t, 'count', n) order by n desc), '[]'::jsonb) into v_pairs
    from (select w.from_stage f, w.to_stage t, count(*) n from public.quote_stage_warnings w
           where w.at > now() - interval '30 days' group by 1, 2 order by 3 desc limit 20) z;
  return jsonb_build_object('tracking', coalesce(s.tracking_enabled, true), 'guard_mode', coalesce(s.guard_mode, 'warn'),
    'emit_events', coalesce(s.emit_events, true), 'updated_at', s.updated_at,
    'transitions_30d', (select count(*) from public.quote_stage_transitions t where t.at > now() - interval '30 days' and t.source <> 'backfill'),
    'warnings_30d', (select count(*) from public.quote_stage_warnings w where w.at > now() - interval '30 days'),
    'studios_enforcing', (select count(*) from public.app_config c where c.key = 'stage_machine' and c.value ->> 'guardMode' = 'enforce'),
    'events_pending', (select count(*) from public.domain_events e where e.id > coalesce((select min(k.last_id) from public.domain_event_cursors k), 0)),
    'illegal_moves', v_pairs);
end $$;

create or replace function public.hq_set_stage_machine(p_tracking boolean, p_guard_mode text, p_emit_events boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-stage-machine: HQ operator at aal2, audited by _hq_wgate
begin
  if p_guard_mode is not null and p_guard_mode not in ('off', 'warn', 'enforce') then
    raise exception 'guard mode must be off, warn or enforce' using errcode = '22023'; end if;
  perform public._hq_wgate('hq.stage_machine.set', 'helm_stage_settings', 'singleton',
    jsonb_strip_nulls(jsonb_build_object('tracking', p_tracking, 'guard_mode', p_guard_mode, 'emit_events', p_emit_events)));
  insert into public.helm_stage_settings(id) values (true) on conflict (id) do nothing;
  update public.helm_stage_settings s
     set tracking_enabled = coalesce(p_tracking, s.tracking_enabled), guard_mode = coalesce(p_guard_mode, s.guard_mode),
         emit_events = coalesce(p_emit_events, s.emit_events), updated_at = now(), updated_by = auth.uid()
   where s.id;
  return public.hq_stage_machine();
end $$;

-- ---- 10) domain events: how automations subscribe (service role only) ---------------------------------------------------
-- A consumer (an edge function / cron tick, e.g. 'reminders' or 'follow-ups') calls
--   select * from domain_events_pull('reminders', array['quote.viewed','quote.approved'], 100);
-- handles the rows (idempotently - keyed by the event id), then
--   select domain_events_ack('reminders', <the highest id it handled>);
-- The cursor never moves backwards; an unknown consumer starts at the current end (no replay of history) unless it
-- passes p_from_start = true the first time.
create or replace function public.domain_events_pull(p_consumer text, p_types text[] default null, p_limit integer default 100,
                                                    p_from_start boolean default false)
returns setof public.domain_events language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-domain-events
declare v_last bigint;
begin
  if p_consumer is null or p_consumer !~ '^[a-z0-9_.-]{2,60}$' then raise exception 'bad consumer name' using errcode = '22023'; end if;
  insert into public.domain_event_cursors(consumer, last_id)
    values (p_consumer, case when coalesce(p_from_start, false) then 0 else coalesce((select max(e.id) from public.domain_events e), 0) end)
  on conflict (consumer) do nothing;
  select k.last_id into v_last from public.domain_event_cursors k where k.consumer = p_consumer;
  return query select e.* from public.domain_events e
    where e.id > v_last and (p_types is null or e.type = any(p_types))
    order by e.id limit greatest(1, least(coalesce(p_limit, 100), 1000));
end $$;

create or replace function public.domain_events_ack(p_consumer text, p_last_id bigint)
returns bigint language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-domain-events
declare v bigint;
begin
  update public.domain_event_cursors k set last_id = greatest(k.last_id, coalesce(p_last_id, 0)), updated_at = now()
   where k.consumer = p_consumer returning k.last_id into v;
  if v is null then raise exception 'unknown consumer %', p_consumer using errcode = 'P0002'; end if;
  return v;
end $$;

-- ---- 11) time-based expiry: record links that ran out (pg_cron every 30 min when installed) ---------------------------
create or replace function public.quote_stage_sweep(p_limit integer default 500)
returns integer language plpgsql volatile security definer set search_path = '' as $$
-- helm-0263-stage-machine
declare r record; n int := 0;
begin
  for r in
    select q.id from public.quotes q join public.quote_stage_current c on c.quote_ref = q.id
     where q.approval_status = 'sent' and q.approval_token_expires_at is not null
       and q.approval_token_expires_at <= now() and c.stage in ('sent', 'viewed')
     order by q.approval_token_expires_at limit greatest(1, least(coalesce(p_limit, 500), 5000))
  loop
    begin
      if public._r23_stage_sync(r.id, 'sweep') is not null then n := n + 1; end if;
    exception when others then raise warning 'helm 0263 sweep: % (%)', r.id, sqlerrm;
    end;
  end loop;
  return n;
end $$;

-- ---- 12) grants ------------------------------------------------------------------------------------------------------
do $$ declare f text; begin
  -- internal: definer helpers / writers - never callable from the API
  foreach f in array array['_r23_quote_stage_now(uuid)', '_r23_source()', '_r23_reason(uuid, timestamptz)', '_r23_guard_mode(uuid)',
                           '_r23_stage_sync(uuid, text)', 'quote_stage_sweep(integer)',
                           'domain_events_pull(text, text[], integer, boolean)', 'domain_events_ack(text, bigint)'] loop
    execute 'revoke all on function public.' || f || ' from public';
    if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.' || f || ' from anon'; end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on function public.' || f || ' from authenticated'; end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant execute on function public.' || f || ' to service_role'; end if;
  end loop;
  -- the app (signed-in studio users; every one re-checks studio + access itself)
  foreach f in array array['quote_stage_history(uuid)', 'quote_stage_list(uuid[])', 'stage_machine_settings()',
                           'set_stage_machine_settings(text, boolean)', 'hq_stage_machine()',
                           'hq_set_stage_machine(boolean, text, boolean)', 'quote_stage_allowed(text, text)',
                           'helm_quote_stage(text, text, text, boolean, boolean, boolean, text, boolean)',
                           'helm_quote_stage_label(text)', 'helm_quote_stage_order(text)'] loop
    execute 'revoke all on function public.' || f || ' from public';
    if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.' || f || ' from anon'; end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'grant execute on function public.' || f || ' to authenticated'; end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant execute on function public.' || f || ' to service_role'; end if;
  end loop;
end $$;

-- ---- 12b) trigger functions are never callable from the API; the studio read-only guard (0045 / 0183) on the four
--      studio tables (an ended trial / suspended studio writes nothing new - the stage trigger's own exception block
--      keeps the original write safe either way) ------------------------------------------------------------------------
do $$ declare f text; t text; begin
  foreach f in array array['tg_r23_stage()', 'tg_r23_stage_guard()', 'tg_r23_append_only()'] loop
    execute 'revoke all on function public.' || f || ' from public';
    if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function public.' || f || ' from anon'; end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on function public.' || f || ' from authenticated'; end if;
  end loop;
  if to_regprocedure('public.tg_studio_read_only()') is not null then
    foreach t in array array['quote_stage_transitions', 'quote_stage_current', 'quote_stage_warnings', 'domain_events'] loop
      if not exists (select 1 from pg_trigger g where g.tgrelid = to_regclass('public.' || t) and g.tgname = 'zzz_studio_read_only') then
        execute format('create trigger zzz_studio_read_only before insert or update or delete on public.%I for each row execute function public.tg_studio_read_only(%L)', t, 'org_id');
      end if;
    end loop;
  end if;
end $$;

-- ---- 13) trial retention (0184): the four studio tables are this studio's event records ------------------------------------
do $$ declare v_def text; begin
  if to_regprocedure('public._tr184_purge_tables()') is null then return; end if;
  v_def := pg_get_functiondef('public._tr184_purge_tables()'::regprocedure);
  if position('''quote_stage_transitions''' in v_def) > 0 then return; end if;
  -- the way 0241 adds its tables: just before 'quotes', only while 'quotes' appears exactly once
  if (length(v_def) - length(replace(v_def, '''quotes''', ''))) / length('''quotes''') <> 1 then
    raise notice '0263: _tr184_purge_tables has an unexpected body - left unchanged'; return;
  end if;
  execute replace(v_def, '''quotes''',
    '''quote_stage_transitions'', ''quote_stage_current'', ''quote_stage_warnings'', ''domain_events'', ''quotes''');
end $$;

-- ---- 14) BACKFILL (insert-only): the stage every existing quote is at when tracking begins -------------------------------
do $$ declare n int; begin
  with s as (
    select q.id, q.org_id, public._r23_quote_stage_now(q.id) as stage, q.status, q.approval_status, q.lifecycle_stage
      from public.quotes q
     where q.org_id is not null and not exists (select 1 from public.quote_stage_current c where c.quote_ref = q.id)
  ), t as (
    insert into public.quote_stage_transitions(org_id, quote_ref, from_stage, to_stage, source, via, legal, detail)
      select s.org_id, s.id, null, s.stage, 'backfill', '0263', true,
             jsonb_strip_nulls(jsonb_build_object('status', s.status, 'approval_status', s.approval_status,
               'lifecycle_stage', s.lifecycle_stage, 'note', 'recorded when stage tracking began'))
        from s where s.stage is not null
      returning id, org_id, quote_ref, to_stage
  )
  insert into public.quote_stage_current(quote_ref, org_id, stage, since, last_transition_id)
    select t.quote_ref, t.org_id, t.to_stage, now(), t.id from t
  on conflict (quote_ref) do nothing;
  get diagnostics n = row_count;
  raise notice '0263: backfilled % quote stage(s)', n;
end $$;

-- ---- 15) pg_cron, ONLY if it is already installed (never created here) ----------------------------------------------------
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin
      if not exists (select 1 from cron.job where jobname = 'helm_quote_stage_sweep') then
        perform cron.schedule('helm_quote_stage_sweep', '*/30 * * * *', 'select public.quote_stage_sweep(500)');
      end if;
    exception when others then
      raise notice '0263: pg_cron present but the sweep could not be scheduled (%); opening the timeline self-heals instead', sqlerrm;
    end;
  end if;
end $$;

commit;

-- VERIFY (every row must say ok = true)
select item, ok from (values
  ('01 tables present with RLS on', (select count(*) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relrowsecurity
       and c.relname in ('quote_stage_transitions', 'quote_stage_current', 'quote_stage_warnings', 'quote_stage_moves', 'domain_events', 'domain_event_cursors', 'helm_stage_settings')) = 7),
  ('02 every quote has a current stage', not exists (select 1 from public.quotes q where q.org_id is not null
       and not exists (select 1 from public.quote_stage_current c where c.quote_ref = q.id))),
  ('03 stored stage = live stage for every quote (links that ran out since are caught by the sweep / next read)',
     not exists (select 1 from public.quote_stage_current c join public.quotes q on q.id = c.quote_ref
       where c.stage <> public._r23_quote_stage_now(q.id) and c.stage not in ('sent', 'viewed'))),
  ('04 triggers installed (record on quotes / closure / link opens + deferred guard)',
     (select count(*) from pg_trigger where tgname in ('zz_r23_stage', 'zz_r23_stage_upd', 'zzzzzz_r23_stage_guard') and not tgisinternal) = 5),
  ('05 default: tracking on, WARN mode, events on', exists (select 1 from public.helm_stage_settings s where s.id and s.tracking_enabled and s.emit_events)
     and (select guard_mode from public.helm_stage_settings where id) in ('warn', 'off', 'enforce')),
  ('06 allowed moves seeded', (select count(*) from public.quote_stage_moves) >= 100),
  ('07 no quote_id column on the new tables (empty-draft cleanup unaffected)', not exists (select 1 from information_schema.columns
       where table_schema = 'public' and column_name = 'quote_id' and table_name in ('quote_stage_transitions', 'quote_stage_current', 'quote_stage_warnings', 'domain_events'))),
  ('08 app API cannot write the history', not has_table_privilege('authenticated', 'public.quote_stage_transitions', 'INSERT')
     and not has_table_privilege('authenticated', 'public.domain_events', 'INSERT') and not has_table_privilege('anon', 'public.quote_stage_transitions', 'SELECT')),
  ('09 trial retention classifies the new tables', to_regprocedure('public._tr184_purge_tables()') is null
     or public._tr184_purge_tables() @> array['quote_stage_transitions', 'quote_stage_current', 'quote_stage_warnings', 'domain_events'])
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 05/7: APPLY-0264.sql
-- In plain words: Payment schedules: built-in 30/50/20, 50/50, 100% upfront + the studio's own templates, added automatically when a client approves (only when the event has no milestones); payment reminders ON by default; overdue bell; a recorded payment marks every milestone it fully covers as paid.
-- ##########################################################################################
-- APPLY-0264.sql - paste into the Supabase SQL editor (STAGING first; production only when the owner says go).
-- Run AFTER the applied releases through 0255 (needs 0156, 0200, 0212, 0250 - all already applied).
-- r23 payment schedules (HoneyBook / Dubsado / Stripe model):
--   * Control Center -> Payment schedules: built-in 30 / 50 / 20 (default), 50 / 50, 100% upfront + the studio's own;
--     the default is added to an event automatically when the client approves (only when it has NO milestones);
--   * payment reminders ON by default (3 days before, on the day, 3 days after) for studios that never saved the
--     reminder card; per-event "Pause automatic reminders"; reminders carry the UPI ID / payment note / live link;
--   * studio bell "Client payment overdue" (once per payment); recording a payment marks every milestone it fully
--     covers as paid; client page shows the schedule (paid / part paid / due / overdue) + how to pay.
-- Nothing deleted or overwritten; existing comms_settings rows keep their choices. Safe to run twice. ASCII only.
-- OWNER STEPS (staging first, then production):
--   1  Paste this whole file and Run. Every VERIFY row at the bottom must say ok = true.
--   2  Deploy the site. No edge function change (comms-dispatch already sends pay_reminder rows when deployed).
--   3  Control Center -> Payment schedules: check the default, add the studio UPI ID / bank note.
--   4  Check: approve a test quote -> Logistics -> Payments shows 3 payments; record the advance -> first one Paid.
begin;
-- 0264_payment_schedules.sql - CANONICAL forward-only.
-- REQUIRES 0003 + 0027 + 0042 + 0110 + 0125 (milestones + money guards, helm_invoice_total, record_payment chain),
--          0036 / 0078 / 0250 (notification catalog chain), 0078 + 0092 + 0155 + 0195 + 0200 + 0212 (comms automation:
--          comms_settings, _comms_queue_pay, comms_tick, comms_outbox_claim), 0156 (record_payment wrappers),
--          0045 (tg_studio_read_only), 0004 (tg_quote_org_match), 0097 (quotes.is_demo), 0184 (trial retention lists).
--
-- In plain words (r23 owner, INDUSTRY-BENCHMARK-PLAN F4 #7 - the HoneyBook / Dubsado / Stripe invoicing model):
--   1  PAYMENT SCHEDULE TEMPLATES (Control Center -> Payment schedules). A template is 1-10 payments; each payment
--      has a name, an amount (a % of the quote total, a fixed amount, or "Balance" = whatever is left) and a due
--      rule (N days after approval, or N days before / after the event day). Built in (always there, never stored):
--        "30 / 50 / 20"  : 30% on approval, 50% 15 days before the event, 20% on the event day  (the default)
--        "50 / 50"       : 50% on approval, 50% 7 days before the event
--        "100% upfront"  : 100% on approval
--      A studio can add its own (custom), pick the default, or archive one (never deleted).
--   2  APPLIED AUTOMATICALLY when a quote is approved (approval_status -> approved / paid) or confirmed, only when
--      the event has NO milestones yet (an existing schedule is never overwritten or added to), only for real events
--      (not sample / demo, not cancelled / archived / deleted) and only while the studio switch "apply automatically"
--      is on (default on). Amounts are worked out from the invoice total (quote total incl. GST + approved change
--      orders - the same figure the overpayment guards use); whole rupees, the last / Balance payment takes the
--      rounding so the schedule always adds up to the total exactly. A due date before the approval day becomes the
--      approval day. A staff member can also apply a template by hand on an event without a schedule (with preview).
--      The automatic step never blocks an approval: any problem is logged as a warning and skipped.
--   3  REMINDERS ON BY DEFAULT. The 0078 payment reminders (e-mail / WhatsApp to the client, queued in comms_outbox;
--      sent only by the dormant comms-dispatch) now default ON for a studio that never saved its automatic-messages
--      settings, with the cadence 3 days before the due date, on the due date and 3 days after (overdue) - all still
--      editable in Control Center (Automatic client messages). A studio that already saved a choice keeps it (no
--      stored row is changed). Per event: "Pause automatic reminders" (Logistics -> Payments / the schedule card)
--      stops new automatic reminders for that event and skips any still waiting; "Send reminder now" still works.
--      Reminders now carry the studio's pay details: the live online payment link when one is open (never a
--      simulated one), the studio UPI ID and a short payment note (Control Center -> Payment schedules).
--   4  STUDIO BELL on overdue: once per payment, the day after its due date (within 30 days), while it is not fully
--      paid - kind 'payment_overdue', a money notice (admins + roles with Finance view by default; 0036 rules).
--   5  RECORDING A PAYMENT marks milestones paid: after record_payment / record_settlement_payment, every milestone
--      the money received now FULLY covers is marked paid, in schedule order (due date, then order); a part payment
--      leaves the milestone open and shows as "part paid". The 15-minute comms_tick does the same for money that came
--      in another way (online payment). The receipt (quote_payments, receipt number) is unchanged; the 0003 / 0110 /
--      0125 money guards still cap everything.
--   6  READ RPCs: payment_schedule_for_quote (staff, Finance view: rows with paid / part paid / due / overdue, receipts,
--      pause state, templates) and public_payment_schedule (client page by its approval token: the schedule with
--      paid / due / overdue and how to pay).
-- Changes: 4 new tables (RLS on; reads through RPCs or same-studio policies; no API-role write privilege), new
-- functions, 1 AFTER trigger on quotes (inserts milestones only when there are none), wrappers (renamed ONCE to
-- *__pre0264, bodies kept, not callable by the app): record_payment, record_settlement_payment, comms_tick,
-- comms_outbox_claim, _comms_queue_pay, notification_catalog, notification_type_of; _comms_cfg re-issued (defaults
-- only); comms_settings column DEFAULTS pay_enabled -> true and pay_max_overdue -> 1 (existing rows untouched);
-- trial retention lists patched in place. No existing row is updated or deleted by this file, no table / column /
-- policy dropped. Additive + idempotent: safe to run twice. ASCII only.
-- ROLLBACK (manual, only if ever needed; no data involved): update public.payment_schedule_settings set auto_apply =
--   false, overdue_bell = false (per studio), or fully: drop trigger zzz_pst_auto_schedule on public.quotes; for each
--   wrapped f: drop function public.f(...); alter function public.f__pre0264(...) rename to f; restore its grants;
--   alter table public.comms_settings alter column pay_enabled set default false, alter column pay_max_overdue set
--   default 3; re-run the 0078 _comms_cfg body. The new tables can stay (unused).

do $$ begin
  if to_regclass('public.payment_milestones') is null or to_regclass('public.quote_payments') is null then
    raise exception 'STOP 0264: payment_milestones / quote_payments are missing'; end if;
  if to_regprocedure('public.helm_invoice_total(uuid)') is null then raise exception 'STOP 0264: apply 0110 first'; end if;
  if to_regprocedure('public.has_area(text,text)') is null or to_regprocedure('public.current_org_id()') is null then
    raise exception 'STOP 0264: has_area / current_org_id are missing'; end if;
  if to_regprocedure('public.tg_studio_read_only()') is null or to_regprocedure('public.tg_quote_org_match()') is null then
    raise exception 'STOP 0264: apply 0004 + 0045 first'; end if;
  if to_regclass('public.comms_settings') is null or to_regclass('public.comms_outbox') is null
     or to_regprocedure('public._comms_cfg(uuid)') is null then raise exception 'STOP 0264: apply 0078 first'; end if;
  if to_regprocedure('public._comms_money(numeric,text)') is null or to_regprocedure('public._comms_date(date,uuid)') is null
     or to_regprocedure('public._comms_client_to(jsonb,text,uuid)') is null or to_regprocedure('public._comms_quote_cur(uuid)') is null then
    raise exception 'STOP 0264: apply 0092 first'; end if;
  if to_regprocedure('public.comms_outbox_claim(integer)') is null or to_regprocedure('public.comms_tick()') is null then
    raise exception 'STOP 0264: comms_outbox_claim / comms_tick are missing'; end if;
  if to_regprocedure('public.record_payment__pre0156(uuid,numeric,text,text,uuid,text,text)') is null then
    raise exception 'STOP 0264: apply 0156 first'; end if;
  if to_regprocedure('public.notification_catalog__pre0250()') is null then raise exception 'STOP 0264: apply 0250 first'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quotes' and column_name = 'is_demo') then
    raise exception 'STOP 0264: apply 0097 first (quotes.is_demo)'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quote_payments' and column_name = 'link_expires_at') then
    raise exception 'STOP 0264: apply 0027 first (quote_payments.link_expires_at)'; end if;
end $$;

-- ---- 1) tables -----------------------------------------------------------------------------------------------------
create table if not exists public.payment_schedule_settings (
  org_id              uuid primary key references public.organizations(id) on delete cascade,
  auto_apply          boolean not null default true,
  default_template_id uuid,
  default_builtin     text not null default '30-50-20' check (default_builtin in ('30-50-20', '50-50', '100-upfront')),
  overdue_bell        boolean not null default true,
  upi_id              text check (upi_id is null or upi_id ~ '^[A-Za-z0-9._-]{2,64}@[A-Za-z0-9.-]{2,64}$'),
  pay_note            text check (pay_note is null or (char_length(pay_note) <= 300 and pay_note !~ '[<>]')),
  updated_at          timestamptz not null default now(),
  updated_by          uuid
);

create table if not exists public.payment_schedule_templates (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organizations(id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 1 and 80 and name !~ '[<>]'),
  lines       jsonb not null check (jsonb_typeof(lines) = 'array' and jsonb_array_length(lines) between 1 and 10),
  archived_at timestamptz,
  created_at  timestamptz not null default now(),
  created_by  uuid,
  updated_at  timestamptz not null default now(),
  updated_by  uuid
);
create unique index if not exists payment_schedule_templates_name_uq
  on public.payment_schedule_templates(org_id, lower(btrim(name))) where archived_at is null;
create index if not exists payment_schedule_templates_org_idx on public.payment_schedule_templates(org_id);

create table if not exists public.payment_schedule_quote_prefs (
  quote_id         uuid primary key references public.quotes(id) on delete cascade,
  org_id           uuid not null references public.organizations(id) on delete cascade,
  reminders_paused boolean not null default false,
  paused_at        timestamptz,
  paused_by        uuid,
  applied_at       timestamptz,
  applied_by       uuid,
  applied_source   text check (applied_source is null or applied_source in ('auto', 'manual')),
  applied_template text check (applied_template is null or char_length(applied_template) <= 80),
  updated_at       timestamptz not null default now()
);
create index if not exists payment_schedule_quote_prefs_org_idx on public.payment_schedule_quote_prefs(org_id);

create table if not exists public.payment_overdue_alerts (
  milestone_id uuid primary key,
  org_id       uuid not null references public.organizations(id) on delete cascade,
  quote_id     uuid not null references public.quotes(id) on delete cascade,
  due_date     date,
  notified_at  timestamptz not null default now()
);
create index if not exists payment_overdue_alerts_org_idx on public.payment_overdue_alerts(org_id, notified_at desc);

alter table public.payment_schedule_settings enable row level security;
alter table public.payment_schedule_templates enable row level security;
alter table public.payment_schedule_quote_prefs enable row level security;
alter table public.payment_overdue_alerts enable row level security;
do $$ declare t text; begin
  foreach t in array array['payment_schedule_settings', 'payment_schedule_templates', 'payment_schedule_quote_prefs', 'payment_overdue_alerts'] loop
    execute format('revoke all on table public.%I from public', t);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on table public.%I from anon', t); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on table public.%I from authenticated', t); end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant select on table public.%I to service_role', t); end if;
    -- suspended / ended-trial studios are read-only for signed-in callers (0045 guard; cron + service role pass)
    execute format('drop trigger if exists zzz_studio_read_only on public.%I', t);
    execute format('create trigger zzz_studio_read_only before insert or update or delete on public.%I for each row execute function public.tg_studio_read_only(%L)', t, 'org_id');
  end loop;
  foreach t in array array['payment_schedule_quote_prefs', 'payment_overdue_alerts'] loop
    execute format('drop trigger if exists zz_quote_org_match on public.%I', t);
    execute format('create trigger zz_quote_org_match before insert or update on public.%I for each row execute function public.tg_quote_org_match()', t);
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select on table public.payment_schedule_settings to authenticated';
    execute 'grant select on table public.payment_schedule_templates to authenticated';
    execute 'grant select on table public.payment_schedule_quote_prefs to authenticated';
  end if;
end $$;
drop policy if exists pst_settings_read on public.payment_schedule_settings;
create policy pst_settings_read on public.payment_schedule_settings for select to authenticated
  using (org_id = (select public.current_org_id()) and (public.has_area('controls', 'view') or public.has_area('finance', 'view')));
drop policy if exists pst_templates_read on public.payment_schedule_templates;
create policy pst_templates_read on public.payment_schedule_templates for select to authenticated
  using (org_id = (select public.current_org_id()) and (public.has_area('controls', 'view') or public.has_area('finance', 'view')));
drop policy if exists pst_prefs_read on public.payment_schedule_quote_prefs;
create policy pst_prefs_read on public.payment_schedule_quote_prefs for select to authenticated
  using (org_id = (select public.current_org_id()) and public.has_area('finance', 'view'));

-- trial retention (0184): templates + per-event prefs + bell bookkeeping are studio records (purged with the trial's
-- data, before quotes); the studio settings row is kept like comms_settings
do $$ declare v_def text; begin
  if to_regprocedure('public._tr184_purge_tables()') is null then return; end if;
  v_def := pg_get_functiondef('public._tr184_purge_tables()'::regprocedure);
  if position('''payment_schedule_quote_prefs''' in v_def) > 0 then return; end if;
  if position('''quote_payments'', ''payment_milestones'',' in v_def) = 0 then
    raise notice '0264: _tr184_purge_tables has an unexpected body - left unchanged'; return; end if;
  execute replace(v_def, '''quote_payments'', ''payment_milestones'',',
    '''quote_payments'', ''payment_milestones'', ''payment_overdue_alerts'', ''payment_schedule_quote_prefs'', ''payment_schedule_templates'',');
end $$;
do $$ declare v_def text; begin
  if to_regprocedure('public._tr184_keep_tables()') is null then return; end if;
  v_def := pg_get_functiondef('public._tr184_keep_tables()'::regprocedure);
  if position('''payment_schedule_settings''' in v_def) > 0 then return; end if;
  if position('''comms_settings'', ' in v_def) = 0 then
    raise notice '0264: _tr184_keep_tables has an unexpected body - left unchanged'; return; end if;
  execute replace(v_def, '''comms_settings'', ', '''comms_settings'', ''payment_schedule_settings'', ');
end $$;

-- ---- 2) templates: built-ins, validation, the arithmetic (internal) ------------------------------------------------
create or replace function public._pst_builtins()
returns jsonb language sql immutable set search_path = '' as $$
  -- pay-schedule-0264: the three built-in templates (always available, never stored)
  select $b$[
    {"key":"builtin:30-50-20","name":"30 / 50 / 20","builtin":true,"lines":[
      {"label":"Advance (30%)","kind":"percent","value":30,"anchor":"approval","offset_days":0},
      {"label":"Second payment (50%)","kind":"percent","value":50,"anchor":"event","offset_days":-15},
      {"label":"Final balance (20%)","kind":"percent","value":20,"anchor":"event","offset_days":0}]},
    {"key":"builtin:50-50","name":"50 / 50","builtin":true,"lines":[
      {"label":"Advance (50%)","kind":"percent","value":50,"anchor":"approval","offset_days":0},
      {"label":"Balance (50%)","kind":"percent","value":50,"anchor":"event","offset_days":-7}]},
    {"key":"builtin:100-upfront","name":"100% upfront","builtin":true,"lines":[
      {"label":"Full payment (100%)","kind":"percent","value":100,"anchor":"approval","offset_days":0}]}
  ]$b$::jsonb;
$$;

-- one template's payments, checked + normalised; raises 22023 in plain words
create or replace function public._pst_lines_clean(p jsonb)
returns jsonb language plpgsql immutable set search_path = '' as $$
declare e jsonb; i integer := 0; v_out jsonb := '[]'::jsonb; v_pct numeric := 0; v_bal integer := 0; v_fixed integer := 0;
  v_label text; v_kind text; v_val numeric; v_anchor text; v_off integer; v_raw text;
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) = 0 then
    raise exception 'Add at least one payment to the schedule.' using errcode = '22023'; end if;
  if jsonb_array_length(p) > 10 then raise exception 'A schedule can have at most 10 payments.' using errcode = '22023'; end if;
  for e in select x from jsonb_array_elements(p) with ordinality t(x, n) order by n loop
    i := i + 1;
    if jsonb_typeof(e) <> 'object' then raise exception 'Payment %: not a valid payment.', i using errcode = '22023'; end if;
    v_label := btrim(coalesce(e ->> 'label', ''));
    if char_length(v_label) not between 1 and 80 or v_label ~ '[<>[:cntrl:]]' then
      raise exception 'Payment %: enter a name of up to 80 characters (no < or >).', i using errcode = '22023'; end if;
    v_kind := coalesce(nullif(btrim(coalesce(e ->> 'kind', '')), ''), 'percent');
    if v_kind not in ('percent', 'fixed', 'balance') then
      raise exception 'Payment %: choose percent, fixed amount or balance.', i using errcode = '22023'; end if;
    v_val := null;
    if v_kind <> 'balance' then
      v_raw := btrim(coalesce(e ->> 'value', ''));
      if v_raw !~ '^[0-9]{1,10}(\.[0-9]{1,2})?$' then
        raise exception 'Payment %: enter the amount as a number (up to 2 decimals).', i using errcode = '22023'; end if;
      v_val := v_raw::numeric;
      if v_kind = 'percent' and (v_val <= 0 or v_val > 100) then
        raise exception 'Payment %: the percentage must be more than 0 and at most 100.', i using errcode = '22023'; end if;
      if v_kind = 'fixed' and v_val <= 0 then
        raise exception 'Payment %: the amount must be more than 0.', i using errcode = '22023'; end if;
    end if;
    v_anchor := coalesce(nullif(btrim(coalesce(e ->> 'anchor', '')), ''), 'approval');
    if v_anchor not in ('approval', 'event') then
      raise exception 'Payment %: the due date counts from the approval or from the event day.', i using errcode = '22023'; end if;
    v_raw := btrim(coalesce(e ->> 'offset_days', '0'));
    if v_raw !~ '^-?[0-9]{1,3}$' or abs(v_raw::integer) > 365 then
      raise exception 'Payment %: days must be a whole number from -365 to 365.', i using errcode = '22023'; end if;
    v_off := v_raw::integer;
    if v_anchor = 'approval' and v_off < 0 then
      raise exception 'Payment %: a payment can''t be due before the approval.', i using errcode = '22023'; end if;
    if v_kind = 'percent' then v_pct := v_pct + v_val; elsif v_kind = 'fixed' then v_fixed := v_fixed + 1; else v_bal := v_bal + 1; end if;
    v_out := v_out || jsonb_build_array(jsonb_build_object('label', v_label, 'kind', v_kind, 'value', v_val,
                                                           'anchor', v_anchor, 'offset_days', v_off));
  end loop;
  if v_bal > 1 then raise exception 'Use at most one "Balance" payment.' using errcode = '22023'; end if;
  if v_pct > 100.001 then raise exception 'The percentages add up to more than 100%%.' using errcode = '22023'; end if;
  if v_bal = 0 and (v_fixed > 0 or abs(v_pct - 100) > 0.001) then
    raise exception 'The payments must add up to 100%% - or add a "Balance" payment that takes whatever is left.' using errcode = '22023'; end if;
  return v_out;
end $$;

-- the schedule for a total: [{seq, label, amount, due_date}] (zero rows dropped). Whole units; the Balance line (or,
-- without one, the last line) takes the remainder so the rows add up to the total exactly. Never more than the total.
create or replace function public._pst_compute(p_lines jsonb, p_total numeric, p_from date, p_event date)
returns jsonb language plpgsql immutable set search_path = '' as $$
declare e jsonb; n bigint; v_rows jsonb := '[]'::jsonb; v_run numeric := 0; v_amt numeric; v_due date; v_bal integer; v_last integer := -1;
  v_left numeric;
begin
  if p_total is null or p_total <= 0 or p_lines is null or jsonb_typeof(p_lines) <> 'array' then return '[]'::jsonb; end if;
  for e, n in select x, t.n from jsonb_array_elements(p_lines) with ordinality t(x, n) order by t.n loop
    v_due := case when e ->> 'anchor' = 'event' then case when p_event is null then null else p_event + coalesce((e ->> 'offset_days')::integer, 0) end
                  else p_from + coalesce((e ->> 'offset_days')::integer, 0) end;
    if v_due is not null and p_from is not null and v_due < p_from then v_due := p_from; end if;
    v_left := greatest(p_total - v_run, 0);
    v_amt := case e ->> 'kind'
      when 'balance' then null
      when 'fixed' then least(round((e ->> 'value')::numeric, 2), v_left)
      else least(round(p_total * (e ->> 'value')::numeric / 100), v_left) end;
    if e ->> 'kind' = 'balance' then v_bal := (n - 1)::integer; end if;
    v_run := v_run + coalesce(v_amt, 0);
    v_rows := v_rows || jsonb_build_array(jsonb_build_object('seq', n, 'label', e ->> 'label', 'amount', v_amt, 'due_date', v_due));
    v_last := (n - 1)::integer;
  end loop;
  if v_last < 0 then return '[]'::jsonb; end if;
  if v_bal is not null then
    v_rows := jsonb_set(v_rows, array[v_bal::text, 'amount'], to_jsonb(round(greatest(p_total - v_run, 0), 2)));
  elsif abs(p_total - v_run) > 0 then
    v_rows := jsonb_set(v_rows, array[v_last::text, 'amount'],
                        to_jsonb(round(greatest(coalesce((v_rows -> v_last ->> 'amount')::numeric, 0) + (p_total - v_run), 0), 2)));
  end if;
  return coalesce((select jsonb_agg(r order by (r ->> 'seq')::integer) from jsonb_array_elements(v_rows) r
                    where coalesce((r ->> 'amount')::numeric, 0) > 0), '[]'::jsonb);
end $$;

-- the studio's calendar day (IST unless the studio says otherwise)
create or replace function public._pst_today(p_org uuid)
returns date language plpgsql stable security definer set search_path = '' as $$
declare v_tz text;
begin
  select coalesce(nullif(btrim(o.timezone), ''), 'Asia/Kolkata') into v_tz from public.organizations o where o.id = p_org;
  return (now() at time zone coalesce(v_tz, 'Asia/Kolkata'))::date;
exception when others then return (now() at time zone 'Asia/Kolkata')::date;
end $$;

-- a template by key ('builtin:<k>' or a studio template id); null key = the studio default. -> {key, name, lines} | null
create or replace function public._pst_resolve(p_org uuid, p_key text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare s public.payment_schedule_settings; t public.payment_schedule_templates; v_key text := nullif(btrim(coalesce(p_key, '')), '');
begin
  if v_key is null then
    select * into s from public.payment_schedule_settings x where x.org_id = p_org;
    if s.default_template_id is not null then
      select * into t from public.payment_schedule_templates x where x.id = s.default_template_id and x.org_id = p_org and x.archived_at is null;
      if t.id is not null then return jsonb_build_object('key', t.id::text, 'name', t.name, 'lines', t.lines); end if;
    end if;
    v_key := 'builtin:' || coalesce(s.default_builtin, '30-50-20');
  end if;
  if v_key like 'builtin:%' then
    return (select b - 'builtin' from jsonb_array_elements(public._pst_builtins()) b where b ->> 'key' = v_key limit 1);
  end if;
  if v_key !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return null; end if;
  select * into t from public.payment_schedule_templates x where x.id = v_key::uuid and x.org_id = p_org and x.archived_at is null;
  if t.id is null then return null; end if;
  return jsonb_build_object('key', t.id::text, 'name', t.name, 'lines', t.lines);
end $$;

-- write the schedule for an event that has none. -> {applied, reason?, rows, template}. Never touches existing rows.
create or replace function public._pst_apply(p_quote uuid, p_key text, p_source text, p_actor uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare q public.quotes; v_t jsonb; v_rows jsonb; r jsonb; v_total numeric; v_n integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('helm:pay:quote:' || p_quote::text, 0));
  select * into q from public.quotes x where x.id = p_quote;
  if q.id is null then return jsonb_build_object('applied', false, 'reason', 'no_event'); end if;
  if exists (select 1 from public.payment_milestones m where m.quote_id = q.id) then
    return jsonb_build_object('applied', false, 'reason', 'has_schedule'); end if;
  v_total := public.helm_invoice_total(q.id);
  if v_total is null or v_total <= 0 then return jsonb_build_object('applied', false, 'reason', 'no_total'); end if;
  v_t := public._pst_resolve(q.org_id, p_key);
  if v_t is null then return jsonb_build_object('applied', false, 'reason', 'no_template'); end if;
  v_rows := public._pst_compute(v_t -> 'lines', v_total, public._pst_today(q.org_id), q.event_date);
  if jsonb_array_length(v_rows) = 0 then return jsonb_build_object('applied', false, 'reason', 'no_rows'); end if;
  for r in select x from jsonb_array_elements(v_rows) x loop
    insert into public.payment_milestones(quote_id, org_id, label, due_date, amount, status, seq, note, created_by)
      values (q.id, q.org_id, r ->> 'label', (r ->> 'due_date')::date, (r ->> 'amount')::numeric, 'due', (r ->> 'seq')::integer,
              left('Payment schedule: ' || coalesce(v_t ->> 'name', 'template'), 200), p_actor);
    v_n := v_n + 1;
  end loop;
  insert into public.payment_schedule_quote_prefs(quote_id, org_id, applied_at, applied_by, applied_source, applied_template)
    values (q.id, q.org_id, now(), p_actor, p_source, left(v_t ->> 'name', 80))
    on conflict (quote_id) do update set applied_at = excluded.applied_at, applied_by = excluded.applied_by,
      applied_source = excluded.applied_source, applied_template = excluded.applied_template, updated_at = now();
  insert into public.audit_log(actor, action, entity, entity_id, quote_id, changed, org_id)
    values (p_actor, 'payment_schedule.applied', 'quotes', q.id::text, q.id,
            jsonb_build_object('template', v_t ->> 'name', 'source', p_source, 'rows', v_n, 'total', v_total), q.org_id);
  return jsonb_build_object('applied', true, 'rows', v_n, 'template', v_t ->> 'name', 'schedule', v_rows);
end $$;

-- ---- 3) applied automatically on approval / confirmation -------------------------------------------------------------
create or replace function public._pst_tg_quote_approved()
returns trigger language plpgsql security definer set search_path = '' as $$
-- pay-schedule-0264: never blocks the approval - any problem is a warning and the schedule is skipped
declare v_on boolean;
begin
  begin
    if not ((coalesce(new.approval_status, '') in ('approved', 'paid') and coalesce(old.approval_status, '') not in ('approved', 'paid'))
            or (coalesce(new.status, '') = 'confirmed' and coalesce(old.status, '') <> 'confirmed')) then return null; end if;
    if coalesce(new.is_demo, false) or new.deleted_at is not null or new.archived_at is not null
       or coalesce(new.status, '') = 'cancelled' then return null; end if;
    select coalesce((select s.auto_apply from public.payment_schedule_settings s where s.org_id = new.org_id), true) into v_on;
    if not v_on then return null; end if;
    if exists (select 1 from public.payment_milestones m where m.quote_id = new.id) then return null; end if;
    perform public._pst_apply(new.id, null, 'auto', auth.uid());
  exception when others then raise warning 'pay-schedule-0264: automatic schedule skipped (% %)', sqlstate, sqlerrm;
  end;
  return null;
end $$;
drop trigger if exists zzz_pst_auto_schedule on public.quotes;
create trigger zzz_pst_auto_schedule after update of approval_status, status on public.quotes
  for each row execute function public._pst_tg_quote_approved();

-- ---- 4) money received covers milestones (schedule order, fully covered only) ----------------------------------------
create or replace function public._pst_allocate(p_quote uuid)
returns integer language plpgsql volatile security definer set search_path = '' as $$
declare v_credit numeric; m record; v_n integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('helm:pay:quote:' || p_quote::text, 0));
  select coalesce(sum(qp.amount), 0) into v_credit from public.quote_payments qp where qp.quote_id = p_quote and qp.status = 'paid';
  v_credit := v_credit - coalesce((select sum(pm.amount) from public.payment_milestones pm where pm.quote_id = p_quote and pm.status = 'paid'), 0);
  if v_credit <= 0.005 then return 0; end if;
  for m in select pm.id, pm.amount from public.payment_milestones pm
            where pm.quote_id = p_quote and pm.status in ('due', 'invoiced') and coalesce(pm.amount, 0) > 0
            order by pm.due_date nulls last, pm.seq, pm.created_at, pm.id
  loop
    exit when v_credit + 0.005 < m.amount;          -- in order: the first one not fully covered stays open (part paid)
    update public.payment_milestones set status = 'paid', paid_at = now() where id = m.id;
    v_credit := v_credit - m.amount; v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

do $$ begin
  if to_regprocedure('public.record_payment__pre0264(uuid,numeric,text,text,uuid,text,text)') is null then
    alter function public.record_payment(uuid, numeric, text, text, uuid, text, text) rename to record_payment__pre0264;
  end if;
  if to_regprocedure('public.record_settlement_payment__pre0264(uuid,numeric,text,text,uuid,text,text)') is null then
    alter function public.record_settlement_payment(uuid, numeric, text, text, uuid, text, text) rename to record_settlement_payment__pre0264;
  end if;
end $$;
create or replace function public.record_payment(p_quote uuid, p_amount numeric, p_method text default 'cash', p_receipt_no text default null,
                                                 p_milestone uuid default null, p_note text default null, p_idempotency_key text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
-- pay-schedule-0264: the receipt row is written to quote_payments by record_payment__pre0264 (ledger + caps unchanged),
-- then every milestone the money now fully covers is paid
declare v_out jsonb; v_n integer := 0;
begin
  v_out := public.record_payment__pre0264(p_quote, p_amount, p_method, p_receipt_no, p_milestone, p_note, p_idempotency_key);
  if not coalesce((v_out ->> 'idempotent_replay')::boolean, false) then
    begin v_n := public._pst_allocate(p_quote);
    exception when others then v_n := 0; raise warning 'pay-schedule-0264: milestone cover skipped (%)', sqlstate;
    end;
    if v_n > 0 then v_out := v_out || jsonb_build_object('milestones_covered', v_n); end if;
  end if;
  return v_out;
end $$;
create or replace function public.record_settlement_payment(p_quote uuid, p_amount numeric, p_method text default 'cash', p_receipt_no text default null,
                                                            p_milestone uuid default null, p_note text default null, p_idempotency_key text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
-- pay-schedule-0264: the receipt row is written to quote_payments by record_settlement_payment__pre0264 (ledger + caps
-- unchanged), then every milestone the money now fully covers is paid
declare v_out jsonb; v_n integer := 0;
begin
  v_out := public.record_settlement_payment__pre0264(p_quote, p_amount, p_method, p_receipt_no, p_milestone, p_note, p_idempotency_key);
  if not coalesce((v_out ->> 'idempotent_replay')::boolean, false) then
    begin v_n := public._pst_allocate(p_quote);
    exception when others then v_n := 0; raise warning 'pay-schedule-0264: milestone cover skipped (%)', sqlstate;
    end;
    if v_n > 0 then v_out := v_out || jsonb_build_object('milestones_covered', v_n); end if;
  end if;
  return v_out;
end $$;

-- ---- 5) reminders: on by default, paused per event, with pay details ------------------------------------------------
-- column DEFAULTS only (a row saved from now on starts with reminders on, -3 / 0 / +3); existing rows are not changed
alter table public.comms_settings alter column pay_enabled set default true;
alter table public.comms_settings alter column pay_max_overdue set default 1;

-- the 0078 body with the new defaults for a studio that never saved its settings (pay reminders on, one overdue step)
create or replace function public._comms_cfg(p_org uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  -- pay-schedule-0264: payment reminders default ON (3 days before, on the day, 3 days after)
  select jsonb_build_object(
    'pay_enabled', coalesce(s.pay_enabled, true),
    'pay_channels', to_jsonb(coalesce(s.pay_channels, array['email']::text[])),
    'pay_before_days', coalesce(s.pay_before_days, 3),
    'pay_on_due', coalesce(s.pay_on_due, true),
    'pay_every_days', coalesce(s.pay_every_days, 3),
    'pay_max_overdue', coalesce(s.pay_max_overdue, 1),
    'pay_template', coalesce(s.pay_template, public._comms_default_pay_template()),
    'fu_enabled', coalesce(s.fu_enabled, false),
    'fu_channels', to_jsonb(coalesce(s.fu_channels, array['email']::text[])),
    'fu_delay_days', coalesce(s.fu_delay_days, 3),
    'fu_max', coalesce(s.fu_max, 2),
    'fu_template', coalesce(s.fu_template, public._comms_default_fu_template()),
    'low_stock_enabled', coalesce(s.low_stock_enabled, true),
    'wa_forward_enabled', coalesce(s.wa_forward_enabled, false),
    'wa_forward_roles', coalesce(s.wa_forward_roles, '{}'::jsonb),
    'studio_whatsapp', s.studio_whatsapp,
    'updated_at', s.updated_at)
  from (select 1) one left join public.comms_settings s on s.org_id = p_org;
$$;

-- how the client can pay: the open LIVE online link (never a simulated one), the studio UPI ID and note
create or replace function public._pst_pay_details(p_quote uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'link', (select qp.link_url from public.quote_payments qp
              where qp.quote_id = q.id and qp.status = 'created' and not coalesce(qp.simulated, true)
                and coalesce(qp.link_url, '') ~ '^https://[^\s<>"]+$' and char_length(qp.link_url) <= 500
                and (qp.link_expires_at is null or qp.link_expires_at > now())
              order by qp.created_at desc limit 1),
    'upi', s.upi_id, 'note', s.pay_note)
  from public.quotes q left join public.payment_schedule_settings s on s.org_id = q.org_id
  where q.id = p_quote;
$$;
create or replace function public._pst_pay_text(p jsonb)
returns text language sql immutable set search_path = '' as $$
  select nullif(concat_ws(' | ',
    case when nullif(p ->> 'link', '') is not null then 'Pay online: ' || (p ->> 'link') end,
    case when nullif(p ->> 'upi', '') is not null then 'UPI: ' || (p ->> 'upi') end,
    nullif(btrim(coalesce(p ->> 'note', '')), '')), '');
$$;

do $$ begin
  if to_regprocedure('public._comms_queue_pay__pre0264(uuid,text,text,boolean,uuid)') is null then
    alter function public._comms_queue_pay(uuid, text, text, boolean, uuid) rename to _comms_queue_pay__pre0264;
  end if;
end $$;
-- the 0092 body + (a) a paused event gets no AUTOMATIC reminder ("Send reminder now" still works) and (b) the pay
-- details: {pay_link} {upi} {pay_details} placeholders, appended when the template has none of them
create or replace function public._comms_queue_pay(p_milestone uuid, p_stage text, p_status_text text, p_manual boolean, p_actor uuid)
returns integer language plpgsql volatile security definer set search_path = '' as $$
-- pay-schedule-0264
declare m public.payment_milestones; q public.quotes; v_cfg jsonb; ch text; v_to text; v_text text; v_n integer := 0; v_rows integer;
  v_studio text; v_key text; v_pay jsonb; v_pay_text text; v_tpl text;
begin
  select * into m from public.payment_milestones x where x.id = p_milestone;
  if m.id is null or m.status not in ('due', 'invoiced') or coalesce(m.amount, 0) <= 0 then return 0; end if;
  select * into q from public.quotes x where x.id = m.quote_id;
  if q.id is null or q.org_id is distinct from m.org_id or not public._comms_quote_live(q.id) then return 0; end if;
  if not coalesce(p_manual, false) and exists (select 1 from public.payment_schedule_quote_prefs p
                                                where p.quote_id = q.id and p.reminders_paused) then return 0; end if;
  v_cfg := public._comms_cfg(q.org_id);
  select o.name into v_studio from public.organizations o where o.id = q.org_id;
  v_pay := public._pst_pay_details(q.id);
  v_pay_text := public._pst_pay_text(v_pay);
  v_tpl := v_cfg ->> 'pay_template';
  if v_pay_text is not null and position('{pay_details}' in v_tpl) = 0 and position('{pay_link}' in v_tpl) = 0
     and position('{upi}' in v_tpl) = 0 then v_tpl := v_tpl || ' {pay_details}'; end if;
  v_text := public._comms_render(v_tpl, jsonb_build_object(
    'client', coalesce(nullif(btrim(q.client ->> 'name'), ''), 'there'), 'studio', coalesce(v_studio, 'your planner'),
    'event', coalesce(nullif(btrim(q.title), ''), 'your event'), 'label', m.label, 'amount', public._comms_money(m.amount, public._comms_quote_cur(q.id)),
    'due', coalesce(public._comms_date(m.due_date, q.org_id), 'soon'), 'status', p_status_text,
    'pay_link', coalesce(v_pay ->> 'link', ''), 'upi', coalesce(v_pay ->> 'upi', ''), 'pay_details', coalesce(v_pay_text, '')));
  foreach ch in array public._comms_channels(v_cfg, 'pay_channels') loop
    v_to := public._comms_client_to(q.client, ch, q.org_id);
    if v_to is null then continue; end if;
    v_key := case when p_manual then 'pay:now:' || m.id || ':' || ch || ':' || floor(extract(epoch from now()) / 600)::bigint
                  else 'pay:' || m.id || ':' || p_stage || ':' || ch end;
    insert into public.comms_outbox(org_id, quote_id, milestone_id, purpose, channel, recipient, payload, dedupe_key, created_by)
      values (q.org_id, q.id, m.id, 'pay_reminder', ch, v_to,
              jsonb_build_object('subject', 'Payment reminder - ' || coalesce(nullif(btrim(q.title), ''), 'your event'),
                                 'text', v_text, 'stage', p_stage, 'manual', p_manual, 'studio', v_studio,
                                 'pay_link', v_pay ->> 'link'),
              v_key, p_actor)
      on conflict (dedupe_key) do nothing;
    get diagnostics v_rows = row_count;
    v_n := v_n + v_rows;
  end loop;
  return v_n;
end $$;

do $$ begin
  if to_regprocedure('public.comms_outbox_claim__pre0264(integer)') is null then
    alter function public.comms_outbox_claim(integer) rename to comms_outbox_claim__pre0264;
  end if;
end $$;
-- a paused event: automatic reminders still waiting are skipped (never sent); then the claim as before
create or replace function public.comms_outbox_claim(p_limit integer default 25)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- pay-schedule-0264
begin
  update public.comms_outbox c set status = 'skipped', sent_at = now()
   where c.sent_at is null and c.status = 'pending' and c.purpose = 'pay_reminder'
     and not coalesce((c.payload ->> 'manual')::boolean, false)
     and exists (select 1 from public.payment_schedule_quote_prefs p where p.quote_id = c.quote_id and p.reminders_paused);
  return public.comms_outbox_claim__pre0264(p_limit);
end $$;

-- ---- 6) notification type: client payment overdue (money: admins + Finance viewers by default) ---------------------
do $$ declare f text[]; begin
  foreach f slice 1 in array array[['notification_catalog', ''], ['notification_type_of', 'text, text']] loop
    if to_regprocedure(format('public.%s(%s)', f[1] || '__pre0264', f[2])) is null then
      execute format('alter function public.%I(%s) rename to %I', f[1], f[2], f[1] || '__pre0264');
    end if;
  end loop;
end $$;
create or replace function public.notification_catalog()
returns jsonb language sql immutable security definer set search_path = '' as $$
  -- pay-schedule-0264: + payment_overdue (once)
  select case when exists (select 1 from jsonb_array_elements(c) e where e ->> 'type' = 'payment_overdue') then c
    else c || $cat$[
    {"type":"payment_overdue","group":"Finance","label":"Client payment overdue",
     "description":"A client's scheduled payment is past its due date and not fully paid yet (one notice per payment, the day after it was due).",
     "audience":"studio","channels":["in_app"],"required":[],"gated":[],"money":true}
  ]$cat$::jsonb end
  from (select public.notification_catalog__pre0264() as c) x;
$$;
create or replace function public.notification_type_of(p_kind text, p_channel text default null)
returns text language sql immutable security definer set search_path = '' as $$
  -- pay-schedule-0264
  select case when lower(btrim(coalesce(p_kind, ''))) = 'payment_overdue' then 'payment_overdue'
              else public.notification_type_of__pre0264(p_kind, p_channel) end;
$$;

-- ---- 7) the scheduler: comms_tick + overdue bell + money-in covers milestones -------------------------------------
create or replace function public._pst_tick()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare o record; v_today date; m record; r record; v_bells integer := 0; v_cov integer := 0; v_rows integer; v_bell boolean;
begin
  for o in select org.id from public.organizations org loop
    begin
      v_today := public._pst_today(o.id);
      -- money that came in another way (online payment, settlement) covers milestones too
      for r in select q.id from public.quotes q
                where q.org_id = o.id and q.deleted_at is null
                  and exists (select 1 from public.payment_milestones pm where pm.quote_id = q.id and pm.status in ('due', 'invoiced') and pm.amount > 0)
                  and coalesce((select sum(qp.amount) from public.quote_payments qp where qp.quote_id = q.id and qp.status = 'paid'), 0)
                      - coalesce((select sum(pm.amount) from public.payment_milestones pm where pm.quote_id = q.id and pm.status = 'paid'), 0) > 0.005
      loop
        begin v_cov := v_cov + public._pst_allocate(r.id);
        exception when others then raise warning 'pay-schedule-0264: cover skipped (%)', sqlstate;
        end;
      end loop;
      select coalesce((select s.overdue_bell from public.payment_schedule_settings s where s.org_id = o.id), true) into v_bell;
      if v_bell then
        for m in select pm.id, pm.quote_id, pm.label, pm.due_date, q.code
                   from public.payment_milestones pm join public.quotes q on q.id = pm.quote_id
                  where pm.org_id = o.id and q.org_id = o.id and pm.status in ('due', 'invoiced') and coalesce(pm.amount, 0) > 0
                    and pm.due_date between v_today - 30 and v_today - 1
                    and not coalesce(q.is_demo, false) and public._comms_quote_live(q.id)
                    and not exists (select 1 from public.payment_overdue_alerts a where a.milestone_id = pm.id)
        loop
          insert into public.payment_overdue_alerts(milestone_id, org_id, quote_id, due_date)
            values (m.id, o.id, m.quote_id, m.due_date) on conflict (milestone_id) do nothing;
          get diagnostics v_rows = row_count;
          if v_rows > 0 then
            insert into public.notifications(quote_id, channel, kind, status, detail, org_id)
              values (m.quote_id, 'in_app', 'payment_overdue', 'simulated',
                      jsonb_build_object('label', left('Payment overdue: ' || coalesce(m.label, 'payment')
                                           || coalesce(' - ' || m.code, ''), 200),
                                         'via', 'comms', 'source', '0264', 'milestone_id', m.id, 'event_code', m.code,
                                         'due_date', m.due_date, 'days', v_today - m.due_date,
                                         'path', 'logistics.html?quote=' || m.quote_id::text || '#payments'), o.id);
            v_bells := v_bells + 1;
          end if;
        end loop;
      end if;
    exception when others then raise warning 'pay-schedule-0264: studio tick skipped (%)', sqlstate;
    end;
  end loop;
  return jsonb_build_object('overdue_bells', v_bells, 'milestones_covered', v_cov);
end $$;

do $$ begin
  if to_regprocedure('public.comms_tick__pre0264()') is null then
    alter function public.comms_tick() rename to comms_tick__pre0264;
  end if;
end $$;
-- the same pg_cron job (helm_comms_tick, every 15 minutes) runs this: the 0078 / 0092 tick, then the 0264 steps
create or replace function public.comms_tick()
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- pay-schedule-0264
declare v jsonb; v2 jsonb;
begin
  v := public.comms_tick__pre0264();
  begin v2 := public._pst_tick();
  exception when others then v2 := jsonb_build_object('pay_schedule_error', sqlstate);
  end;
  return coalesce(v, '{}'::jsonb) || coalesce(v2, '{}'::jsonb);
end $$;

-- ---- 8) RPCs for the app ----------------------------------------------------------------------------------------------
-- Control Center: read (Control Center or Finance VIEW)
create or replace function public.payment_schedule_settings_get()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); s public.payment_schedule_settings; v_cfg jsonb;
begin
  if auth.uid() is null or v_org is null or not (public.has_area('controls', 'view') or public.has_area('finance', 'view')) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  select * into s from public.payment_schedule_settings x where x.org_id = v_org;
  v_cfg := public._comms_cfg(v_org);
  return jsonb_build_object(
    'auto_apply', coalesce(s.auto_apply, true),
    'overdue_bell', coalesce(s.overdue_bell, true),
    'default_template', coalesce((select t.id::text from public.payment_schedule_templates t
                                   where t.id = s.default_template_id and t.org_id = v_org and t.archived_at is null),
                                 'builtin:' || coalesce(s.default_builtin, '30-50-20')),
    'upi_id', s.upi_id, 'pay_note', s.pay_note, 'updated_at', s.updated_at,
    'can_edit', public.has_area('controls', 'edit'),
    'builtins', public._pst_builtins(),
    'templates', coalesce((select jsonb_agg(jsonb_build_object('key', t.id::text, 'id', t.id, 'name', t.name, 'lines', t.lines,
                                                               'updated_at', t.updated_at) order by lower(t.name))
                             from public.payment_schedule_templates t where t.org_id = v_org and t.archived_at is null), '[]'::jsonb),
    'reminders', jsonb_build_object('enabled', (v_cfg ->> 'pay_enabled')::boolean, 'channels', v_cfg -> 'pay_channels',
      'before_days', (v_cfg ->> 'pay_before_days')::integer, 'on_due', (v_cfg ->> 'pay_on_due')::boolean,
      'every_days', (v_cfg ->> 'pay_every_days')::integer, 'max_overdue', (v_cfg ->> 'pay_max_overdue')::integer,
      'saved', v_cfg ->> 'updated_at' is not null));
end $$;

-- Control Center: write (Control Center EDIT). Only the keys given change.
create or replace function public.payment_schedule_settings_set(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); v_me uuid := auth.uid(); k text; v_def text; v_tid uuid; v_builtin text;
  v_upi text; v_note text;
begin
  if v_me is null or v_org is null or not public.has_area('controls', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'settings must be an object' using errcode = '22023'; end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('auto_apply', 'overdue_bell', 'default_template', 'upi_id', 'pay_note') then
      raise exception 'unknown setting %', k using errcode = '22023'; end if;
  end loop;
  foreach k in array array['auto_apply', 'overdue_bell'] loop
    if p ? k and jsonb_typeof(p -> k) <> 'boolean' then raise exception '% must be true or false', k using errcode = '22023'; end if;
  end loop;
  if p ? 'default_template' then
    v_def := btrim(coalesce(p ->> 'default_template', ''));
    if v_def like 'builtin:%' then
      v_builtin := substr(v_def, 9);
      if v_builtin not in ('30-50-20', '50-50', '100-upfront') then raise exception 'Choose one of the payment schedules.' using errcode = '22023'; end if;
    elsif v_def ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          and exists (select 1 from public.payment_schedule_templates t where t.id = v_def::uuid and t.org_id = v_org and t.archived_at is null) then
      v_tid := v_def::uuid;
    else raise exception 'Choose one of the payment schedules.' using errcode = '22023'; end if;
  end if;
  if p ? 'upi_id' then
    if jsonb_typeof(p -> 'upi_id') not in ('string', 'null') then raise exception 'upi_id must be text' using errcode = '22023'; end if;
    v_upi := nullif(btrim(coalesce(p ->> 'upi_id', '')), '');
    if v_upi is not null and v_upi !~ '^[A-Za-z0-9._-]{2,64}@[A-Za-z0-9.-]{2,64}$' then
      raise exception 'Enter a UPI ID like studio@okbank.' using errcode = '22023'; end if;
  end if;
  if p ? 'pay_note' then
    if jsonb_typeof(p -> 'pay_note') not in ('string', 'null') then raise exception 'pay_note must be text' using errcode = '22023'; end if;
    v_note := nullif(btrim(regexp_replace(coalesce(p ->> 'pay_note', ''), '\s+', ' ', 'g')), '');
    if v_note is not null and (char_length(v_note) > 300 or v_note ~ '[<>]') then
      raise exception 'Keep the payment note to 300 characters, without < or >.' using errcode = '22023'; end if;
  end if;
  insert into public.payment_schedule_settings(org_id) values (v_org) on conflict (org_id) do nothing;
  update public.payment_schedule_settings s set
    auto_apply   = case when p ? 'auto_apply' then (p ->> 'auto_apply')::boolean else s.auto_apply end,
    overdue_bell = case when p ? 'overdue_bell' then (p ->> 'overdue_bell')::boolean else s.overdue_bell end,
    default_template_id = case when p ? 'default_template' then v_tid else s.default_template_id end,
    default_builtin = case when p ? 'default_template' and v_builtin is not null then v_builtin else s.default_builtin end,
    upi_id   = case when p ? 'upi_id' then v_upi else s.upi_id end,
    pay_note = case when p ? 'pay_note' then v_note else s.pay_note end,
    updated_at = now(), updated_by = v_me
   where s.org_id = v_org;
  insert into public.audit_log(actor, action, entity, entity_id, changed, org_id)
    values (v_me, 'payment_schedule.settings', 'payment_schedule_settings', v_org::text, p, v_org);
  return public.payment_schedule_settings_get();
end $$;

-- Control Center: add / change a studio template (Control Center EDIT)
create or replace function public.payment_schedule_template_save(p_id uuid, p_name text, p_lines jsonb)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); v_me uuid := auth.uid(); v_name text := btrim(coalesce(p_name, ''));
  v_lines jsonb; t public.payment_schedule_templates;
begin
  if v_me is null or v_org is null or not public.has_area('controls', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  if char_length(v_name) not between 1 and 80 or v_name ~ '[<>[:cntrl:]]' then
    raise exception 'Give the schedule a name of up to 80 characters (no < or >).' using errcode = '22023'; end if;
  v_lines := public._pst_lines_clean(p_lines);
  begin
    if p_id is null then
      if (select count(*) from public.payment_schedule_templates x where x.org_id = v_org and x.archived_at is null) >= 30 then
        raise exception 'A studio can keep up to 30 payment schedules - archive one first.' using errcode = '22023'; end if;
      insert into public.payment_schedule_templates(org_id, name, lines, created_by, updated_by)
        values (v_org, v_name, v_lines, v_me, v_me) returning * into t;
    else
      update public.payment_schedule_templates x set name = v_name, lines = v_lines, updated_at = now(), updated_by = v_me
       where x.id = p_id and x.org_id = v_org and x.archived_at is null returning * into t;
      if t.id is null then raise exception 'payment schedule not found' using errcode = '42501'; end if;
    end if;
  exception when unique_violation then
    raise exception 'There is already a payment schedule called "%".', v_name using errcode = '22023';
  end;
  insert into public.audit_log(actor, action, entity, entity_id, changed, org_id)
    values (v_me, case when p_id is null then 'payment_schedule.template_added' else 'payment_schedule.template_changed' end,
            'payment_schedule_templates', t.id::text, jsonb_build_object('name', t.name, 'lines', t.lines), v_org);
  return jsonb_build_object('key', t.id::text, 'id', t.id, 'name', t.name, 'lines', t.lines, 'updated_at', t.updated_at);
end $$;

-- Control Center: archive (never delete) a studio template; the default falls back to the built-in one
create or replace function public.payment_schedule_template_archive(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); v_me uuid := auth.uid(); v_name text;
begin
  if v_me is null or v_org is null or not public.has_area('controls', 'edit') then raise exception 'not authorized' using errcode = '42501'; end if;
  update public.payment_schedule_templates x set archived_at = now(), updated_at = now(), updated_by = v_me
   where x.id = p_id and x.org_id = v_org and x.archived_at is null returning x.name into v_name;
  if v_name is null then raise exception 'payment schedule not found' using errcode = '42501'; end if;
  update public.payment_schedule_settings s set default_template_id = null, updated_at = now(), updated_by = v_me
   where s.org_id = v_org and s.default_template_id = p_id;
  insert into public.audit_log(actor, action, entity, entity_id, changed, org_id)
    values (v_me, 'payment_schedule.template_archived', 'payment_schedule_templates', p_id::text, jsonb_build_object('name', v_name), v_org);
  return jsonb_build_object('archived', true, 'name', v_name);
end $$;

-- one event's schedule (Finance VIEW, own studio): rows with paid / part paid / due / overdue, receipts, pause, templates
create or replace function public.payment_schedule_for_quote(p_quote uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); q public.quotes; v_today date; v_paid numeric; v_left numeric; v_total numeric;
  m record; v_rows jsonb := '[]'::jsonb; v_take numeric; v_rem numeric; v_state text; pr public.payment_schedule_quote_prefs;
  v_cfg jsonb; v_next jsonb; v_sched numeric := 0;
begin
  if auth.uid() is null or v_org is null then raise exception 'not authorized' using errcode = '42501'; end if;
  select * into q from public.quotes x where x.id = p_quote and x.org_id = v_org;
  if q.id is null then raise exception 'event not found' using errcode = '42501'; end if;
  if not public.has_area('finance', 'view') then raise exception 'not authorized' using errcode = '42501'; end if;
  v_today := public._pst_today(v_org);
  v_total := public.helm_invoice_total(q.id);
  select coalesce(sum(qp.amount), 0) into v_paid from public.quote_payments qp where qp.quote_id = q.id and qp.status = 'paid';
  v_left := greatest(v_paid - coalesce((select sum(pm.amount) from public.payment_milestones pm where pm.quote_id = q.id and pm.status = 'paid'), 0), 0);
  for m in select pm.* from public.payment_milestones pm where pm.quote_id = q.id
            order by pm.due_date nulls last, pm.seq, pm.created_at, pm.id loop
    if m.status <> 'waived' then v_sched := v_sched + coalesce(m.amount, 0); end if;
    if m.status = 'paid' then v_take := coalesce(m.amount, 0); v_rem := 0; v_state := 'paid';
    elsif m.status = 'waived' then v_take := 0; v_rem := 0; v_state := 'waived';
    else
      v_take := least(greatest(coalesce(m.amount, 0), 0), v_left); v_left := v_left - v_take;
      v_rem := round(greatest(coalesce(m.amount, 0), 0) - v_take, 2);
      v_state := case when coalesce(m.amount, 0) > 0 and v_rem <= 0.005 then 'paid'
                      when m.due_date is not null and m.due_date < v_today then 'overdue'
                      when v_take > 0.005 then 'part_paid'
                      else m.status end;
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object('id', m.id, 'seq', m.seq, 'label', m.label, 'due_date', m.due_date,
      'amount', m.amount, 'status', m.status, 'state', v_state, 'paid', round(v_take, 2), 'remaining', v_rem,
      'days', case when m.due_date is not null then m.due_date - v_today end, 'paid_at', m.paid_at));
    if v_next is null and v_state in ('due', 'invoiced', 'overdue', 'part_paid') then
      v_next := jsonb_build_object('id', m.id, 'label', m.label, 'due_date', m.due_date, 'remaining', v_rem, 'state', v_state);
    end if;
  end loop;
  select * into pr from public.payment_schedule_quote_prefs x where x.quote_id = q.id;
  v_cfg := public._comms_cfg(v_org);
  return jsonb_build_object(
    'quote_id', q.id, 'code', q.code, 'currency', coalesce(public._comms_quote_cur(q.id), 'INR'),
    'event_date', q.event_date, 'today', v_today,
    'total', round(v_total, 2), 'paid', round(v_paid, 2), 'scheduled', round(v_sched, 2),
    'outstanding', round(greatest(greatest(v_total, v_sched) - v_paid, 0), 2),
    'rows', v_rows, 'next', v_next,
    'receipts', coalesce((select jsonb_agg(jsonb_build_object('receipt_no', qp.receipt_no, 'amount', qp.amount, 'method', qp.method,
                                                              'paid_at', coalesce(qp.paid_at, qp.created_at)) order by coalesce(qp.paid_at, qp.created_at))
                            from public.quote_payments qp where qp.quote_id = q.id and qp.status = 'paid'), '[]'::jsonb),
    'paused', coalesce(pr.reminders_paused, false), 'paused_at', pr.paused_at,
    'applied', case when pr.applied_at is not null then jsonb_build_object('at', pr.applied_at, 'source', pr.applied_source, 'template', pr.applied_template) end,
    'reminders', jsonb_build_object('enabled', (v_cfg ->> 'pay_enabled')::boolean,
      'before_days', (v_cfg ->> 'pay_before_days')::integer, 'on_due', (v_cfg ->> 'pay_on_due')::boolean,
      'every_days', (v_cfg ->> 'pay_every_days')::integer, 'max_overdue', (v_cfg ->> 'pay_max_overdue')::integer,
      'client_reachable', exists (select 1 from unnest(public._comms_channels(v_cfg, 'pay_channels')) c
                                   where public._comms_client_to(q.client, c, v_org) is not null)),
    'can_edit', public.has_area('finance', 'edit'),
    'can_pause', public.has_area('finance', 'edit') or public.has_area('quotes', 'edit'),
    'default_template', (public._pst_resolve(v_org, null)) ->> 'key',
    'templates', (select coalesce(jsonb_agg(jsonb_build_object('key', b ->> 'key', 'name', b ->> 'name')), '[]'::jsonb)
                    from jsonb_array_elements(public._pst_builtins()) b)
                 || coalesce((select jsonb_agg(jsonb_build_object('key', t.id::text, 'name', t.name) order by lower(t.name))
                                from public.payment_schedule_templates t where t.org_id = v_org and t.archived_at is null), '[]'::jsonb));
end $$;

-- apply a template by hand to an event WITHOUT a schedule (Finance EDIT); p_preview = show the rows, write nothing
create or replace function public.payment_schedule_apply(p_quote uuid, p_template text default null, p_preview boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); v_me uuid := auth.uid(); q public.quotes; v_t jsonb; v_total numeric; v_r jsonb;
begin
  if v_me is null or v_org is null then raise exception 'not authorized' using errcode = '42501'; end if;
  select * into q from public.quotes x where x.id = p_quote and x.org_id = v_org;
  if q.id is null then raise exception 'event not found' using errcode = '42501'; end if;
  if not (case when coalesce(p_preview, false) then public.has_area('finance', 'view') else public.has_area('finance', 'edit') end) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if exists (select 1 from public.payment_milestones m where m.quote_id = q.id) then
    raise exception 'This event already has a payment schedule - change it in Logistics > Payments.' using errcode = '22023'; end if;
  v_total := public.helm_invoice_total(q.id);
  if v_total is null or v_total <= 0 then raise exception 'Price the quote first - the schedule is worked out from its total.' using errcode = '22023'; end if;
  v_t := public._pst_resolve(v_org, p_template);
  if v_t is null then raise exception 'Choose one of the payment schedules.' using errcode = '22023'; end if;
  if coalesce(p_preview, false) then
    return jsonb_build_object('applied', false, 'preview', true, 'template', v_t ->> 'name', 'total', v_total,
      'schedule', public._pst_compute(v_t -> 'lines', v_total, public._pst_today(v_org), q.event_date));
  end if;
  if q.deleted_at is not null or q.archived_at is not null or coalesce(q.status, '') = 'cancelled' then
    raise exception 'This event is cancelled or archived.' using errcode = '22023'; end if;
  v_r := public._pst_apply(q.id, v_t ->> 'key', 'manual', v_me);
  if not coalesce((v_r ->> 'applied')::boolean, false) then
    raise exception 'The payment schedule could not be added (%).', coalesce(v_r ->> 'reason', 'unknown') using errcode = '22023'; end if;
  begin perform public._pst_allocate(q.id);                    -- money already received covers the first payments
  exception when others then raise warning 'pay-schedule-0264: cover skipped (%)', sqlstate;
  end;
  return v_r;
end $$;

-- pause / resume automatic client reminders for one event (Finance or Quotes EDIT, own studio)
create or replace function public.payment_schedule_pause(p_quote uuid, p_paused boolean)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare v_org uuid := public.current_org_id(); v_me uuid := auth.uid(); q public.quotes;
begin
  if v_me is null or v_org is null or not (public.has_area('finance', 'edit') or public.has_area('quotes', 'edit')) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if p_paused is null then raise exception 'say pause or resume' using errcode = '22023'; end if;
  select * into q from public.quotes x where x.id = p_quote and x.org_id = v_org;
  if q.id is null then raise exception 'event not found' using errcode = '42501'; end if;
  insert into public.payment_schedule_quote_prefs(quote_id, org_id, reminders_paused, paused_at, paused_by)
    values (q.id, v_org, p_paused, case when p_paused then now() end, case when p_paused then v_me end)
    on conflict (quote_id) do update set reminders_paused = excluded.reminders_paused,
      paused_at = excluded.paused_at, paused_by = excluded.paused_by, updated_at = now();
  insert into public.audit_log(actor, action, entity, entity_id, quote_id, changed, org_id)
    values (v_me, case when p_paused then 'payment_reminders.paused' else 'payment_reminders.resumed' end,
            'quotes', q.id::text, q.id, jsonb_build_object('paused', p_paused), v_org);
  return jsonb_build_object('paused', p_paused);
end $$;

-- the client page (approval token, signed out): the schedule with paid / due / overdue + how to pay
create or replace function public.public_payment_schedule(p_token uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare q public.quotes; v_today date; v_paid numeric; v_left numeric; m record; v_rows jsonb := '[]'::jsonb;
  v_take numeric; v_rem numeric; v_state text; v_pay jsonb;
begin
  perform public.public_get_quote(p_token);   -- raises on an invalid / expired / shelved link
  select * into q from public.quotes x where x.approval_token = p_token;
  if q.id is null then raise exception 'invalid link' using errcode = '42501'; end if;
  v_today := public._pst_today(q.org_id);
  select coalesce(sum(qp.amount), 0) into v_paid from public.quote_payments qp where qp.quote_id = q.id and qp.status = 'paid';
  v_left := greatest(v_paid - coalesce((select sum(pm.amount) from public.payment_milestones pm where pm.quote_id = q.id and pm.status = 'paid'), 0), 0);
  for m in select pm.* from public.payment_milestones pm where pm.quote_id = q.id and pm.status <> 'waived'
            order by pm.due_date nulls last, pm.seq, pm.created_at, pm.id loop
    if m.status = 'paid' then v_take := coalesce(m.amount, 0); v_rem := 0; v_state := 'paid';
    else
      v_take := least(greatest(coalesce(m.amount, 0), 0), v_left); v_left := v_left - v_take;
      v_rem := round(greatest(coalesce(m.amount, 0), 0) - v_take, 2);
      v_state := case when coalesce(m.amount, 0) > 0 and v_rem <= 0.005 then 'paid'
                      when m.due_date is not null and m.due_date < v_today then 'overdue'
                      when v_take > 0.005 then 'part_paid' else 'due' end;
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object('label', m.label, 'due_date', m.due_date, 'amount', m.amount,
      'state', v_state, 'paid', round(v_take, 2), 'remaining', v_rem));
  end loop;
  v_pay := public._pst_pay_details(q.id);
  return jsonb_build_object('currency', coalesce(public._comms_quote_cur(q.id), 'INR'), 'today', v_today,
    'total', round(public.helm_invoice_total(q.id), 2), 'paid', round(v_paid, 2), 'rows', v_rows,
    'pay', case when v_pay ->> 'link' is null and v_pay ->> 'upi' is null and v_pay ->> 'note' is null then null else v_pay end);
end $$;

-- ---- 9) grants ----------------------------------------------------------------------------------------------------------
do $$ declare f text; begin
  foreach f in array array[
    'public._pst_builtins()', 'public._pst_lines_clean(jsonb)', 'public._pst_compute(jsonb, numeric, date, date)',
    'public._pst_today(uuid)', 'public._pst_resolve(uuid, text)', 'public._pst_apply(uuid, text, text, uuid)',
    'public._pst_tg_quote_approved()', 'public._pst_allocate(uuid)', 'public._pst_pay_details(uuid)', 'public._pst_pay_text(jsonb)',
    'public._pst_tick()', 'public._comms_cfg(uuid)', 'public._comms_queue_pay(uuid, text, text, boolean, uuid)',
    'public._comms_queue_pay__pre0264(uuid, text, text, boolean, uuid)', 'public.comms_outbox_claim(integer)',
    'public.comms_outbox_claim__pre0264(integer)', 'public.comms_tick()', 'public.comms_tick__pre0264()',
    'public.record_payment__pre0264(uuid, numeric, text, text, uuid, text, text)',
    'public.record_settlement_payment__pre0264(uuid, numeric, text, text, uuid, text, text)',
    'public.notification_catalog__pre0264()', 'public.notification_type_of__pre0264(text, text)',
    'public.payment_schedule_settings_get()', 'public.payment_schedule_settings_set(jsonb)',
    'public.payment_schedule_template_save(uuid, text, jsonb)', 'public.payment_schedule_template_archive(uuid)',
    'public.payment_schedule_for_quote(uuid)', 'public.payment_schedule_apply(uuid, text, boolean)',
    'public.payment_schedule_pause(uuid, boolean)', 'public.public_payment_schedule(uuid)',
    'public.record_payment(uuid, numeric, text, text, uuid, text, text)',
    'public.record_settlement_payment(uuid, numeric, text, text, uuid, text, text)',
    'public.notification_catalog()', 'public.notification_type_of(text, text)'] loop
    execute 'revoke all on function ' || f || ' from public';
    if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on function ' || f || ' from anon'; end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on function ' || f || ' from authenticated'; end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    foreach f in array array['public.payment_schedule_settings_get()', 'public.payment_schedule_settings_set(jsonb)',
      'public.payment_schedule_template_save(uuid, text, jsonb)', 'public.payment_schedule_template_archive(uuid)',
      'public.payment_schedule_for_quote(uuid)', 'public.payment_schedule_apply(uuid, text, boolean)',
      'public.payment_schedule_pause(uuid, boolean)', 'public.public_payment_schedule(uuid)',
      'public.record_payment(uuid, numeric, text, text, uuid, text, text)',
      'public.record_settlement_payment(uuid, numeric, text, text, uuid, text, text)',
      'public.notification_catalog()', 'public.notification_type_of(text, text)'] loop
      execute 'grant execute on function ' || f || ' to authenticated';
    end loop;
  end if;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'grant execute on function public.public_payment_schedule(uuid) to anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    foreach f in array array['public.comms_tick()', 'public.comms_outbox_claim(integer)', 'public._pst_tick()',
      'public.record_payment(uuid, numeric, text, text, uuid, text, text)',
      'public.record_settlement_payment(uuid, numeric, text, text, uuid, text, text)',
      'public.notification_catalog()', 'public.notification_type_of(text, text)', 'public._comms_cfg(uuid)',
      'public._comms_queue_pay(uuid, text, text, boolean, uuid)'] loop
      execute 'grant execute on function ' || f || ' to service_role';
    end loop;
  end if;
end $$;

